        DateIdea(id: 61, emoji: "🕹️", title: LText(de: "Online-Spieleabend", en: "Online game night"), details: LText(de: "Schach, Wortspiele oder Party-Apps gegeneinander im Call — mit ewiger Turniertabelle.", en: "Chess, word games, or party apps against each other on a call — with an eternal tournament table."), indoor: true, budget: 0, tags: ["longdistance", "silly"]),
        DateIdea(id: 62, emoji: "📷", title: LText(de: "Foto-Challenge des Tages", en: "Daily photo challenge"), details: LText(de: "Gebt euch morgens ein Motto („etwas Rotes“, „Himmel“) und schickt euch abends euer bestes Foto dazu.", en: "Give each other a morning theme (\"something red\", \"sky\") and send your best matching photo in the evening."), indoor: false, budget: 0, tags: ["longdistance", "creative"], energy: .quick),
        DateIdea(id: 63, emoji: "🥐", title: LText(de: "Virtuelles Frühstücksdate", en: "Virtual breakfast date"), details: LText(de: "Gleiche Uhrzeit, hübsch gedeckter Tisch, frischer Kaffee — nur eben mit Bildschirm in der Tischmitte.", en: "Same time, nicely set table, fresh coffee — just with a screen in the middle of the table."), indoor: true, budget: 0, tags: ["longdistance", "food", "cozy"]),
        DateIdea(id: 64, emoji: "💤", title: LText(de: "Einschlafen im Call", en: "Falling asleep on the call"), details: LText(de: "Lasst den Call einfach laufen, erzählt euch vom Tag und schlaft zusammen ein — fast wie nebeneinander.", en: "Just leave the call running, talk about your day, and fall asleep together — almost like side by side."), indoor: true, budget: 0, tags: ["longdistance", "cozy", "night"]),
        DateIdea(id: 65, emoji: "🧠", title: LText(de: "36-Fragen-Abend auf Distanz", en: "Long-distance 36 questions"), details: LText(de: "Nehmt euch die berühmten 36 Fragen vor — per Call, mit Tee und ganz ohne Zeitdruck.", en: "Take on the famous 36 questions — on a call, with tea, and no time pressure at all."), indoor: true, budget: 0, tags: ["longdistance", "romantic"]),
        DateIdea(id: 66, emoji: "🎥", title: LText(de: "Mini-Vlog vom Tag", en: "Mini day vlog"), details: LText(de: "Filmt euren Tag in 60 Sekunden und schickt euch die Clips am Abend — kleine Fenster in den Alltag des anderen.", en: "Film your day in 60 seconds and send each other the clips in the evening — little windows into each other's day."), indoor: false, budget: 0, tags: ["longdistance", "creative"]),
        DateIdea(id: 67, emoji: "🏛️", title: LText(de: "Touristen in der eigenen Stadt", en: "Tourists in your own city"), details: LText(de: "Bucht eine klassische Stadtführung in eurer eigenen Stadt und tut den ganzen Tag so, als wärt ihr im Urlaub.", en: "Book a classic guided tour of your own city and pretend all day that you're on vacation."), indoor: false, budget: 1, tags: ["adventure", "silly"]),
        DateIdea(id: 68, emoji: "🍇", title: LText(de: "Weingut oder Obsthof", en: "Vineyard or orchard"), details: LText(de: "Fahrt aufs Land, macht eine Verkostung oder pflückt Äpfel — und nehmt eine Kiste für zuhause mit.", en: "Head to the countryside, do a tasting or pick apples — and take a crate home with you."), indoor: false, budget: 2, tags: ["food", "outdoor", "romantic"]),
        DateIdea(id: 69, emoji: "🎸", title: LText(de: "Konzert einer unbekannten Band", en: "Unknown band concert"), details: LText(de: "Kauft Tickets für eine Band, von der ihr noch nie gehört habt — vielleicht entdeckt ihr euren neuen Lieblingssong.", en: "Buy tickets for a band you've never heard of — you might discover your new favorite song."), indoor: true, budget: 2, tags: ["night", "adventure"]),
        DateIdea(id: 70, emoji: "🧗", title: LText(de: "Boulderhalle", en: "Bouldering gym"), details: LText(de: "Leiht euch Schuhe und feuert euch gegenseitig die Wände hoch — Muskelkater am nächsten Tag inklusive.", en: "Rent shoes and cheer each other up the walls — next-day muscle soreness included."), indoor: true, budget: 2, tags: ["adventure"]),
        DateIdea(id: 71, emoji: "🌿", title: LText(de: "Botanischer Garten", en: "Botanical garden"), details: LText(de: "Schlendert durch die Gewächshäuser, sucht die seltsamste Pflanze und gebt ihr einen Spitznamen.", en: "Stroll through the greenhouses, find the strangest plant, and give it a nickname."), indoor: false, budget: 1, tags: ["outdoor", "romantic"]),
        DateIdea(id: 72, emoji: "🛁", title: LText(de: "Schaumbad mit Playlist", en: "Bubble bath with playlist"), details: LText(de: "Fragt euch: Lust auf ein gemeinsames Schaumbad? Badewanne voll, Kerzen an, eure ruhigste Playlist — und danach in die flauschigsten Bademäntel.", en: "Ask each other: up for a shared bubble bath? Fill the tub, light candles, play your calmest playlist — then straight into the fluffiest bathrobes."), indoor: true, budget: 0, tags: ["cozy", "romantic", "athome"]),
        DateIdea(id: 73, emoji: "🍬", title: LText(de: "Schokoladen-Tasting", en: "Chocolate tasting"), details: LText(de: "Fünf Tafeln von günstig bis edel, Notizzettel und große Gefühle: Kürt eure gemeinsame Lieblingssorte.", en: "Five bars from cheap to fancy, note cards, and big emotions: crown your shared favorite."), indoor: true, budget: 1, tags: ["food", "athome", "cozy"]),
        DateIdea(id: 74, emoji: "🏓", title: LText(de: "Tischtennis im Park", en: "Ping-pong in the park"), details: LText(de: "Schnappt euch Schläger und spielt an der Betonplatte um den Titel — der Verlierer holt die Getränke.", en: "Grab paddles and battle for the title at the concrete table — the loser fetches the drinks."), indoor: false, budget: 0, tags: ["outdoor", "silly"]),
        DateIdea(id: 75, emoji: "🖋️", title: LText(de: "Gemeinsames Tagebuch", en: "Shared journal"), details: LText(de: "Startet ein Paar-Tagebuch, in das ihr abwechselnd schreibt — heute füllt ihr gemeinsam die erste Seite.", en: "Start a couple's journal you take turns writing in — today you fill the first page together."), indoor: true, budget: 1, tags: ["creative", "romantic", "athome"]),
        DateIdea(id: 76, emoji: "🌆", title: LText(de: "Aussichtspunkt-Hopping", en: "Viewpoint hopping"), details: LText(de: "Sucht die drei besten Ausblicke eurer Stadt an einem Tag und kürt den schönsten mit einem Foto.", en: "Visit your city's three best views in one day and crown the most beautiful one with a photo."), indoor: false, budget: 0, tags: ["adventure", "outdoor"]),
        DateIdea(id: 77, emoji: "🍹", title: LText(de: "Mocktail-Bar zuhause", en: "Home mocktail bar"), details: LText(de: "Säfte, Sirup, Minze und Crushed Ice: Mixt euch alkoholfreie Signature-Drinks und tauft sie nacheinander.", en: "Juices, syrup, mint, and crushed ice: mix alcohol-free signature drinks and name them after each other."), indoor: true, budget: 1, tags: ["food", "athome", "night"]),
        DateIdea(id: 78, emoji: "🎯", title: LText(de: "Dart-Turnier", en: "Darts tournament"), details: LText(de: "Kneipe oder Wohnzimmer: Best of five — wer verliert, übernimmt eine Woche den Abwasch.", en: "Pub or living room: best of five — the loser does the dishes for a week."), indoor: true, budget: 0, tags: ["silly", "athome"]),
        DateIdea(id: 79, emoji: "📻", title: LText(de: "Schallplatten-Abend", en: "Vinyl night"), details: LText(de: "Stöbert im Plattenladen, kauft eine gemeinsame Platte und hört sie zuhause komplett durch — ohne Skippen.", en: "Browse the record store, buy one shared record, and listen to it at home in full — no skipping."), indoor: true, budget: 2, tags: ["cozy", "night"]),
        DateIdea(id: 80, emoji: "🐦", title: LText(de: "Vogelhäuschen bauen", en: "Building a birdhouse"), details: LText(de: "Baumarkt, Bausatz, etwas Geduld: Baut ein Vogelhäuschen und hängt es gemeinsam vors Fenster.", en: "Hardware store, kit, a little patience: build a birdhouse and hang it outside your window together."), indoor: true, budget: 1, tags: ["creative", "athome"]),
        DateIdea(id: 81, emoji: "🥐", title: LText(de: "Bäckerei-Hopping", en: "Bakery hopping"), details: LText(de: "Samstags früh: drei Bäckereien, drei Teilchen, ein klarer Sieger — und der Sonntag ist auch schon geplant.", en: "Early Saturday: three bakeries, three pastries, one clear winner — and Sunday is already planned."), indoor: false, budget: 1, tags: ["food", "silly"]),
        DateIdea(id: 82, emoji: "🎪", title: LText(de: "Zirkus oder Varieté", en: "Circus or variety show"), details: LText(de: "Gönnt euch einen Abend voller Artistik und Staunen — schick angezogen, versteht sich.", en: "Treat yourselves to an evening of acrobatics and wonder — dressed up, of course."), indoor: true, budget: 3, tags: ["night", "romantic"]),
        DateIdea(id: 83, emoji: "🧭", title: LText(de: "Geocaching", en: "Geocaching"), details: LText(de: "Ladet eine Geocaching-App herunter und hebt euren ersten gemeinsamen Schatz — Logbuch-Eintrag nicht vergessen.", en: "Download a geocaching app and find your first shared treasure — don't forget the logbook entry."), indoor: false, budget: 0, tags: ["adventure", "outdoor"]),
        DateIdea(id: 84, emoji: "🍲", title: LText(de: "Länderküchen-Abend", en: "World cuisine night"), details: LText(de: "Zeigt blind auf eine Weltkarte und kocht ein Gericht aus dem getroffenen Land — Musik von dort läuft dazu.", en: "Point blindly at a world map and cook a dish from the country you hit — with music from there playing along."), indoor: true, budget: 1, tags: ["food", "athome", "creative"]),
        DateIdea(id: 85, emoji: "🚣", title: LText(de: "Tretbootfahren", en: "Pedal boating"), details: LText(de: "Einmal über den See treten, in der Mitte treiben lassen und die mitgebrachten Kekse auspacken.", en: "Pedal across the lake, drift in the middle, and unpack the cookies you brought."), indoor: false, budget: 1, tags: ["outdoor", "romantic"]),
        DateIdea(id: 86, emoji: "💐", title: LText(de: "Blumen-Arrangier-Duell", en: "Flower arranging duel"), details: LText(de: "Gleiches Budget am Blumenstand: Wer bindet den schöneren Strauß? Beide bleiben natürlich bei euch.", en: "Same budget at the flower stand: who ties the prettier bouquet? Both stay at your place, of course."), indoor: true, budget: 1, tags: ["creative", "silly"]),
        DateIdea(id: 87, emoji: "🌕", title: LText(de: "Vollmond-Spaziergang", en: "Full moon walk"), details: LText(de: "Wartet auf die nächste Vollmondnacht und dreht eine Runde im silbernen Licht — Taschenlampe optional.", en: "Wait for the next full moon and take a lap in the silver light — flashlight optional."), indoor: false, budget: 0, tags: ["night", "romantic", "outdoor"], energy: .quick),
        DateIdea(id: 88, emoji: "🧀", title: LText(de: "Käseplatten-Abend", en: "Cheese board night"), details: LText(de: "Baut die schönste Käseplatte eures Lebens: drei Sorten Käse, Trauben, Nüsse, Honig — und viel Zeit.", en: "Build the most beautiful cheese board of your life: three cheeses, grapes, nuts, honey — and plenty of time."), indoor: true, budget: 2, tags: ["food", "cozy", "athome"]),
        DateIdea(id: 89, emoji: "📼", title: LText(de: "Kindheits-Filmabend", en: "Childhood movie night"), details: LText(de: "Zeigt einander den Lieblingsfilm eurer Kindheit und erzählt, warum er damals alles bedeutet hat.", en: "Show each other your childhood favorite movie and explain why it meant everything back then."), indoor: true, budget: 0, tags: ["cozy", "athome"]),
        DateIdea(id: 90, emoji: "🏹", title: LText(de: "Bogenschießen", en: "Archery"), details: LText(de: "Bucht einen Schnupperkurs und findet heraus, wer von euch der heimliche Robin Hood ist.", en: "Book a taster session and find out which of you is the secret Robin Hood."), indoor: false, budget: 2, tags: ["adventure"]),
        DateIdea(id: 91, emoji: "🍉", title: LText(de: "Markt-Frühstück", en: "Market breakfast"), details: LText(de: "Kauft auf dem Wochenmarkt spontan, was euch anlacht, und frühstückt direkt auf der nächsten Bank.", en: "At the farmers' market, spontaneously buy whatever smiles at you and have breakfast right on the nearest bench."), indoor: false, budget: 1, tags: ["food", "outdoor"]),
        DateIdea(id: 92, emoji: "🎹", title: LText(de: "Gemeinsam ein Lied lernen", en: "Learning a song together"), details: LText(de: "Sucht ein einfaches Stück für Ukulele oder Klavier und übt, bis es sitzt — vier Hände sind erlaubt.", en: "Pick an easy piece for ukulele or piano and practice until it sticks — four hands allowed."), indoor: true, budget: 0, tags: ["creative", "athome"]),
        DateIdea(id: 93, emoji: "🌲", title: LText(de: "Waldbaden", en: "Forest bathing"), details: LText(de: "Handys aus, langsam gehen, bewusst lauschen und riechen — und danach Kuchen als Belohnung.", en: "Phones off, walk slowly, consciously listen and smell — then cake as a reward."), indoor: false, budget: 0, tags: ["outdoor", "cozy"]),
        DateIdea(id: 94, emoji: "🕺", title: LText(de: "Wohnzimmer-Disco", en: "Living room disco"), details: LText(de: "Licht aus, Lichterkette an: Jeder legt abwechselnd drei Songs auf, getanzt wird ausnahmslos.", en: "Lights off, fairy lights on: take turns DJing three songs each — dancing is non-negotiable."), indoor: true, budget: 0, tags: ["silly", "athome", "night"]),
        DateIdea(id: 95, emoji: "🍤", title: LText(de: "Tapas-Abend", en: "Tapas night"), details: LText(de: "Viele kleine Teller, ein großer Tisch: Bestellt euch quer durch die Karte und teilt alles.", en: "Lots of small plates, one big table: order your way across the menu and share everything."), indoor: true, budget: 2, tags: ["food", "romantic"]),
        DateIdea(id: 96, emoji: "🚌", title: LText(de: "Endstation-Date", en: "End-of-the-line date"), details: LText(de: "Nehmt einen Bus bis zur Endhaltestelle und erkundet, was es dort zu entdecken gibt — Rückweg zu Fuß erlaubt.", en: "Take a bus to the last stop and explore whatever there is to discover — walking back is allowed."), indoor: false, budget: 0, tags: ["adventure", "silly"]),
        DateIdea(id: 97, emoji: "🧣", title: LText(de: "Gemütlichkeits-Wichteln", en: "Coziness gift swap"), details: LText(de: "Kauft einander für 10 Euro das gemütlichste Ding, das ihr findet — Socken, Kerzen, Kakao, alles zählt.", en: "For 10 euros each, buy the coziest thing you can find for each other — socks, candles, cocoa, everything counts."), indoor: false, budget: 1, tags: ["cozy", "silly"]),
        DateIdea(id: 98, emoji: "🖥️", title: LText(de: "Traumreise planen", en: "Dream trip planning"), details: LText(de: "Plant eure Traumreise bis ins Detail — Route, Hotels, Essen — auch wenn sie erst in fünf Jahren stattfindet.", en: "Plan your dream trip in full detail — route, hotels, food — even if it's five years away."), indoor: true, budget: 0, tags: ["creative", "athome", "romantic"]),
        DateIdea(id: 99, emoji: "⛺", title: LText(de: "Camping am See", en: "Lakeside camping"), details: LText(de: "Zelt, kleiner Grill und Sonnenuntergang am Wasser — morgens weckt euch das Vogelkonzert.", en: "Tent, small grill, and a sunset by the water — in the morning the birds are your alarm clock."), indoor: false, budget: 2, tags: ["adventure", "outdoor", "night"]),
        DateIdea(id: 100, emoji: "🍰", title: LText(de: "Café-Tour", en: "Café crawl"), details: LText(de: "Kaffee im ersten Café, Kuchen im zweiten, Abschluss-Kakao im dritten — Bewertungsbögen nicht vergessen.", en: "Coffee at the first café, cake at the second, a closing cocoa at the third — don't forget the scorecards."), indoor: true, budget: 2, tags: ["food", "cozy"]),
        DateIdea(id: 101, emoji: "🎓", title: LText(de: "Skill-Tausch", en: "Skill swap"), details: LText(de: "Jeder bringt dem anderen an einem Abend etwas bei, das er gut kann — jonglieren, Omelett, Kartentrick.", en: "In one evening, each of you teaches the other something you're good at — juggling, omelets, a card trick."), indoor: true, budget: 0, tags: ["creative", "athome"]),
        DateIdea(id: 102, emoji: "🌈", title: LText(de: "Farben-Date", en: "Color date"), details: LText(de: "Wählt gemeinsam eine Farbe und richtet alles danach: Outfits, Essen, Fotos — je konsequenter, desto lustiger.", en: "Pick one color together and match everything to it: outfits, food, photos — the stricter, the funnier."), indoor: false, budget: 1, tags: ["silly", "creative"]),
        DateIdea(id: 103, emoji: "🦉", title: LText(de: "Nachtwanderung", en: "Night hike"), details: LText(de: "Stirnlampen auf und einen vertrauten Weg im Dunkeln gehen — derselbe Wald, ein völlig neues Gefühl.", en: "Headlamps on and walk a familiar trail in the dark — same forest, a completely new feeling."), indoor: false, budget: 0, tags: ["night", "adventure", "outdoor"]),
        DateIdea(id: 104, emoji: "🍯", title: LText(de: "Frühstück im Bett", en: "Breakfast in bed"), details: LText(de: "Einer schleicht sich früher raus und überrascht den anderen mit einem vollen Tablett und einer Blume.", en: "One of you sneaks out early and surprises the other with a full tray and a flower."), indoor: true, budget: 1, tags: ["cozy", "romantic", "athome"]),
        DateIdea(id: 105, emoji: "🎲", title: LText(de: "Würfel-Date", en: "Dice date"), details: LText(de: "Schreibt sechs Mini-Dates auf, nummeriert sie und würfelt — was fällt, wird sofort gemacht.", en: "Write down six mini dates, number them, and roll the die — whatever comes up happens immediately."), indoor: true, budget: 1, tags: ["silly", "adventure"]),
        DateIdea(id: 106, emoji: "🤳", title: LText(de: "Eigenes Fotoshooting", en: "DIY photo shoot"), details: LText(de: "Selbstauslöser oder Stativ, drei Outfits und goldenes Abendlicht — das beste Bild wird gerahmt.", en: "Self-timer or tripod, three outfits, and golden evening light — the best shot gets framed."), indoor: false, budget: 0, tags: ["creative", "romantic", "outdoor"]),
        DateIdea(id: 107, emoji: "🍨", title: LText(de: "Dessert zuerst", en: "Dessert first"), details: LText(de: "Heute wird das Menü umgedreht: erst Nachtisch, dann Hauptgang — und wer mag, danach noch einen Nachtisch.", en: "Tonight the menu is flipped: dessert first, then the main course — and another dessert after, if you like."), indoor: true, budget: 1, tags: ["food", "silly"]),
        DateIdea(id: 108, emoji: "💦", title: LText(de: "Wasserschlacht im Park", en: "Water fight in the park"), details: LText(de: "Wasserpistolen oder Becher, ein heißer Tag und keine Gnade — Handtücher nicht vergessen.", en: "Water pistols or cups, a hot day, and no mercy — don't forget the towels."), indoor: false, budget: 0, tags: ["silly", "outdoor"]),
        DateIdea(id: 109, emoji: "🧵", title: LText(de: "DIY-Abend", en: "DIY craft night"), details: LText(de: "Makramee, Kerzen ziehen oder Ton: Ein Kit, vier Hände und am Ende ein Werk für die Wohnung.", en: "Macramé, candle making, or clay: one kit, four hands, and in the end a piece for your home."), indoor: true, budget: 1, tags: ["creative", "athome", "cozy"]),
        DateIdea(id: 110, emoji: "🏰", title: LText(de: "Tagesausflug zum Schloss", en: "Day trip to a castle"), details: LText(de: "Sucht ein Schloss oder eine Burg in der Nähe, spaziert durch den Park und erfindet Geschichten über die Bewohner von früher.", en: "Find a castle nearby, stroll through the grounds, and invent stories about the people who once lived there."), indoor: false, budget: 1, tags: ["adventure", "romantic"]),
        DateIdea(id: 111, emoji: "🌮", title: LText(de: "Taco-Abend", en: "Taco night"), details: LText(de: "Baut eine Bau-dir-selbst-Taco-Bar mit viel zu vielen Toppings auf und testet die kühnsten Kombinationen.", en: "Set up a build-your-own taco bar with way too many toppings and test the boldest combinations."), indoor: true, budget: 1, tags: ["food", "athome"]),
        DateIdea(id: 112, emoji: "🔥", title: LText(de: "Lagerfeuer & Stockbrot", en: "Campfire and bread on a stick"), details: LText(de: "Sucht eine offizielle Feuerstelle, bereitet Stockbrotteig vor und erzählt euch Geschichten, bis die Glut ausgeht.", en: "Find an official fire pit, prepare bread-on-a-stick dough, and tell stories until the embers die down."), indoor: false, budget: 0, tags: ["outdoor", "night", "cozy"]),
        DateIdea(id: 113, emoji: "📝", title: LText(de: "Paar-Quiz selbst gemacht", en: "DIY couple quiz"), details: LText(de: "Schreibt je zehn Fragen über euch als Paar und quizzt euch gegenseitig — feierliche Siegerehrung inklusive.", en: "Write ten questions each about you as a couple and quiz each other — solemn award ceremony included."), indoor: true, budget: 0, tags: ["silly", "athome"]),
        DateIdea(id: 114, emoji: "🚡", title: LText(de: "Seilbahn oder Aussichtsturm", en: "Cable car or lookout tower"), details: LText(de: "Fahrt oder steigt nach oben, genießt das Panorama und packt oben ein kleines Picknick aus.", en: "Ride or climb to the top, enjoy the panorama, and unpack a little picnic up there."), indoor: false, budget: 2, tags: ["adventure", "romantic"]),
        DateIdea(id: 115, emoji: "🌹", title: LText(de: "Erstes Date nachspielen", en: "First date reenactment"), details: LText(de: "Spielt euer allererstes Date so originalgetreu wie möglich nach — gleiche Orte, gleiche Getränke, gleiche Nervosität.", en: "Reenact your very first date as faithfully as possible — same places, same drinks, same butterflies."), indoor: false, budget: 2, tags: ["romantic"]),
        DateIdea(id: 116, emoji: "⛳", title: LText(de: "Minigolf-Duell", en: "Mini golf duel"), details: LText(de: "Achtzehn Bahnen, große Gesten und ein Einsatz: Wer verliert, muss den Abend über den Namen „Champion“ für den anderen benutzen.", en: "Eighteen holes, big gestures, and stakes: whoever loses has to call the other \"champion\" for the rest of the evening."), indoor: false, budget: 1, tags: ["silly", "outdoor"]),
        DateIdea(id: 117, emoji: "🛼", title: LText(de: "Rollschuh-Runde", en: "Roller skating date"), details: LText(de: "Leiht euch Rollschuhe oder Skates — und wer mag, hält Händchen dabei. Stürze zählen als Umarmungsangebote.", en: "Rent roller skates — and hold hands if you both like. Falls count as offered hugs."), indoor: false, budget: 1, tags: ["silly", "adventure"]),
        DateIdea(id: 118, emoji: "🧖", title: LText(de: "Sauna-Auszeit", en: "Spa afternoon"), details: LText(de: "Ein Nachmittag Sauna oder Therme: Handys bleiben im Spind, dafür gibt's Ruhe, Wärme und Zeit nur für euch.", en: "An afternoon at the sauna or thermal baths: phones stay in the locker — instead you get quiet, warmth, and time just for you two."), indoor: true, budget: 3, tags: ["cozy", "romantic"]),
        DateIdea(id: 119, emoji: "🥞", title: LText(de: "Pancake-Art-Frühstück", en: "Pancake-art breakfast"), details: LText(de: "Teig in die Quetschflasche und los: Wer zaubert das schönste Pfannkuchen-Porträt vom anderen? Gegessen wird jedes Kunstwerk.", en: "Batter into a squeeze bottle and go: who makes the best pancake portrait of the other? Every artwork gets eaten."), indoor: true, budget: 0, tags: ["food", "athome", "creative"]),
        DateIdea(id: 120, emoji: "🎧", title: LText(de: "Playlist-Spaziergang", en: "Shared-playlist walk"), details: LText(de: "Eine Playlist, ein Kopfhörer-Paar geteilt: Spaziert eure Lieblingsrunde und erzählt euch zu jedem Song eine Erinnerung.", en: "One playlist, one pair of earbuds shared: walk your favorite loop and trade a memory for every song."), indoor: false, budget: 0, tags: ["romantic", "outdoor"]),
        DateIdea(id: 121, emoji: "🚲", title: LText(de: "Feierabend-Radtour", en: "After-work bike ride"), details: LText(de: "Direkt nach der Arbeit aufs Rad, eine neue Route wählen und unterwegs ein Eis oder einen Sundowner einplanen.", en: "Straight onto the bikes after work, pick a new route, and plan an ice cream or sundowner stop along the way."), indoor: false, budget: 0, tags: ["outdoor", "adventure"]),
        DateIdea(id: 122, emoji: "🫖", title: LText(de: "Tee-Verkostung zu Hause", en: "Home tea tasting"), details: LText(de: "Kauft fünf lose Teesorten, brüht sie nacheinander auf und vergebt Punkte für Duft, Farbe und Geschmack.", en: "Buy five loose-leaf teas, brew them one after another, and score each for aroma, color, and taste."), indoor: true, budget: 1, tags: ["cozy", "athome", "food"]),
        DateIdea(id: 123, emoji: "🎸", title: LText(de: "Wohnzimmer-Konzertabend", en: "Living-room concert night"), details: LText(de: "Sucht einen Live-Mitschnitt eurer Lieblingsband, macht das Licht aus und tut so, als wärt ihr in Reihe eins — Eintritt: ein Getränk eurer Wahl.", en: "Find a live recording of your favorite band, kill the lights, and pretend you're in the front row — admission: one drink of your choice."), indoor: true, budget: 0, tags: ["athome", "night", "cozy"]),
        DateIdea(id: 124, emoji: "🎙️", title: LText(de: "Synchron-Podcast-Spaziergang", en: "Synced podcast walk"), details: LText(de: "Startet in euren beiden Städten dieselbe Podcast-Folge und geht dabei spazieren — danach wird im Call diskutiert.", en: "Start the same podcast episode in your two cities and go for a walk — then discuss it on a call afterwards."), indoor: false, budget: 0, tags: ["longdistance", "outdoor"]),
        DateIdea(id: 125, emoji: "♟️", title: LText(de: "Parkschach oder Boule", en: "Park chess or boules"), details: LText(de: "Sucht die Schachbank oder Boule-Bahn in eurem Park und fordert euch zu drei Partien heraus — Publikum ist ausdrücklich willkommen.", en: "Find the chess table or boules pitch in your park and challenge each other to three rounds — spectators very welcome."), indoor: false, budget: 0, tags: ["outdoor", "silly"]),
        DateIdea(id: 126, emoji: "⛸️", title: LText(de: "Eislaufbahn-Date", en: "Ice rink date"), details: LText(de: "Dreht Runden auf der Eisbahn, haltet euch gut fest und belohnt euch danach mit heißem Kakao.", en: "Do laps at the ice rink, hold on tight, and reward yourselves with hot cocoa afterwards."), indoor: false, budget: 1, tags: ["adventure", "romantic"]),
        DateIdea(id: 127, emoji: "🎨", title: LText(de: "Malabend mit Musik", en: "Paint night with music"), details: LText(de: "Zwei Leinwände, ein Motiv und euer Lieblingsalbum — am Ende werden beide Kunstwerke feierlich enthüllt.", en: "Two canvases, one subject, and your favorite album — at the end both artworks get a ceremonial reveal."), indoor: true, budget: 1, tags: ["creative", "athome", "cozy"]),
        // Expansion
        DateIdea(id: 128, emoji: "🍜", title: LText(de: "Ramen-Battle", en: "Ramen battle"), details: LText(de: "Jeder kocht seine eigene Instant-Ramen-Kreation mit drei Extra-Zutaten — probiert beide und kürt den Sieger.", en: "Each of you upgrades instant ramen with three extra toppings — taste both bowls and crown a winner."), indoor: true, budget: 1, tags: ["food", "athome", "silly"]),
        DateIdea(id: 129, emoji: "🌆", title: LText(de: "Blaue-Stunde-Runde", en: "Blue-hour loop"), details: LText(de: "Geht los, wenn die Laternen gerade angehen: einmal ums Viertel, und jeder zeigt dem anderen ein Fenster, hinter dem er gern wohnen würde.", en: "Head out just as the street lamps flick on: one lap around the block, and each of you points out a window you'd love to live behind."), indoor: false, budget: 0, tags: ["outdoor", "romantic"], energy: .quick),
        DateIdea(id: 130, emoji: "📖", title: LText(de: "Buchhandlungs-Wichteln", en: "Bookstore gift swap"), details: LText(de: "Jeder hat 15 Minuten und ein Mini-Budget, um dem anderen das perfekte Buch zu schenken — mit Widmung auf Seite 1.", en: "You each get 15 minutes and a tiny budget to pick the perfect book for the other — dedication on page one required."), indoor: true, budget: 1, tags: ["creative", "cozy"]),
        DateIdea(id: 131, emoji: "🎳", title: LText(de: "Retro-Bowlingabend", en: "Retro bowling night"), details: LText(de: "Bowlen mit Verlierer-Wetten: Wer verliert, übernimmt eine Woche lang den Abwasch — oder den nächsten Liebesgutschein.", en: "Bowling with loser stakes: whoever loses does the dishes for a week — or owes the next love coupon."), indoor: true, budget: 2, tags: ["silly", "adventure"]),
        DateIdea(id: 132, emoji: "🌅", title: LText(de: "Sonnenaufgangs-Fensterplatz", en: "Sunrise window seat"), details: LText(de: "Wer von euch früh raus muss, weckt den anderen fünf Minuten vor Sonnenaufgang: ein Kaffee, ein Fenster, das beste Licht des Tages — danach darf weitergeschlafen werden.", en: "Whoever has the early start wakes the other five minutes before sunrise: one coffee, one window, the best light of the day — then back to sleep is allowed."), indoor: true, budget: 0, tags: ["romantic", "athome"], energy: .quick),
        DateIdea(id: 133, emoji: "🍁", title: LText(de: "Herbstblätter-Herbarium", en: "Autumn-leaf herbarium"), details: LText(de: "Sammelt auf einem Spaziergang die schönsten Blätter, presst sie zuhause in ein dickes Buch und schreibt das Datum dazu — euer erstes gemeinsames Herbarium.", en: "Collect the prettiest leaves on a walk, press them in a heavy book at home, and note the date — your first shared herbarium."), indoor: false, budget: 0, tags: ["outdoor", "creative", "cozy"]),
        DateIdea(id: 134, emoji: "🎮", title: LText(de: "Koop-Spieleabend", en: "Co-op game night"), details: LText(de: "Ein Koop-Spiel, zwei Controller, null Schuldzuweisungen — ihr gewinnt oder verliert zusammen.", en: "One co-op game, two controllers, zero blaming — you win or lose together."), indoor: true, budget: 1, tags: ["athome", "cozy", "silly"]),
        DateIdea(id: 135, emoji: "🫙", title: LText(de: "Fragen-Glas füllen", en: "Filling the question jar"), details: LText(de: "Schreibt zwanzig Fragen auf Zettel, faltet sie in ein Glas und zieht ab jetzt bei jedem Abendessen eine — heute wird das Glas gemeinsam befüllt.", en: "Write twenty questions on slips, fold them into a jar, and from now on draw one at every dinner — tonight you fill the jar together."), indoor: true, budget: 0, tags: ["athome", "creative", "cozy"]),
        DateIdea(id: 136, emoji: "🧑‍🍳", title: LText(de: "Rezept-Erbstück", en: "Heirloom recipe night"), details: LText(de: "Kocht das Familienrezept, mit dem einer von euch aufgewachsen ist — der Anruf bei Mama oder Oma wegen der Geheimzutat ist ausdrücklich erlaubt.", en: "Cook the family recipe one of you grew up with — calling mom or grandma about the secret ingredient is absolutely allowed."), indoor: true, budget: 1, tags: ["food", "athome", "cozy"]),
        DateIdea(id: 137, emoji: "🍳", title: LText(de: "Schichtplan-Dinnerdate", en: "Split-shift dinner date"), details: LText(de: "Einer sitzt beim Frühstück, einer beim Abendbrot: Deckt beide den Tisch, ruft euch an und feiert, dass sich eure Mahlzeiten treffen, auch wenn eure Uhren es nicht tun.", en: "One of you is at breakfast, the other at dinner: both set the table, call each other, and celebrate that your meals can meet even when your clocks don't."), indoor: true, budget: 0, tags: ["longdistance", "food"]),
        DateIdea(id: 138, emoji: "🖼️", title: LText(de: "Fern-Museumsbesuch", en: "Long-distance museum date"), details: LText(de: "Sucht euch eine virtuelle Ausstellung aus, geht im Call gemeinsam durch die Räume und kürt am Ende je ein Lieblingswerk.", en: "Pick a virtual exhibition, wander through the rooms together on a call, and each crown a favorite piece at the end."), indoor: true, budget: 0, tags: ["longdistance", "creative"]),
        DateIdea(id: 139, emoji: "📜", title: LText(de: "Unser Zeitstrahl", en: "Our timeline"), details: LText(de: "Malt euren gemeinsamen Zeitstrahl auf ein großes Blatt: erste Nachricht, erster Kuss, Umzüge, Pannen — und markiert, worauf ihr am meisten stolz seid.", en: "Draw your shared timeline on one big sheet: first message, first kiss, moves, mishaps — then mark what you're proudest of."), indoor: true, budget: 0, tags: ["creative", "athome", "cozy"]),
        DateIdea(id: 140, emoji: "🫧", title: LText(de: "Spa-Abend zu Hause", en: "Home spa evening"), details: LText(de: "Kerzen, Gesichtsmasken, ruhige Playlist — und wer mag, bietet eine Schultermassage an. Handys bleiben im Flugmodus.", en: "Candles, face masks, a calm playlist — and whoever feels like it offers a shoulder rub. Phones stay on airplane mode."), indoor: true, budget: 1, tags: ["cozy", "romantic", "athome"]),
        DateIdea(id: 141, emoji: "📸", title: LText(de: "Ein-Objektiv-Fotosafari", en: "One-lens photo safari"), details: LText(de: "Ein Spaziergang, zehn Motive von einer Liste (etwas Rotes, etwas Altes, uns beide …) — abends werden die Bilder gekürt.", en: "One walk, ten shots from a list (something red, something old, the two of us…) — judge the photos in the evening."), indoor: false, budget: 0, tags: ["creative", "outdoor"]),
        DateIdea(id: 142, emoji: "🕯️", title: LText(de: "Dinner im Kerzenschein-Fort", en: "Blanket-fort candle dinner"), details: LText(de: "Baut ein Kissen-Fort im Wohnzimmer und esst euer Lieblingsgericht darin — Lichterkette statt Deckenlampe.", en: "Build a pillow fort in the living room and eat your favorite meal inside — fairy lights instead of ceiling light."), indoor: true, budget: 1, tags: ["cozy", "athome", "romantic"]),
        // Expansion 2 — quer über Budget, Ort, Jahreszeit und Energie-Level.
        DateIdea(id: 143, emoji: "🚋", title: LText(de: "Endstation Straßenbahn", en: "End-of-the-line tram ride"), details: LText(de: "Nehmt die Tram-Linie, die ihr nie nehmt, bis zur Endstation — dort betretet ihr das erste Café, das offen hat.", en: "Take the tram line you never ride all the way to its last stop — then walk into the first café that's open."), indoor: false, budget: 1, tags: ["adventure", "silly"]),
        DateIdea(id: 144, emoji: "🌰", title: LText(de: "Kastanien-Sammelwette", en: "Chestnut-collecting bet"), details: LText(de: "Stellt im Park einen 20-Minuten-Timer: Wer findet mehr Kastanien? Der Verlierer schuldet dem Gewinner einen Bratapfel.", en: "Set a 20-minute timer in the park: who finds more chestnuts? The loser owes the winner a baked apple."), indoor: false, budget: 0, tags: ["outdoor", "silly"]),
        DateIdea(id: 145, emoji: "🌫️", title: LText(de: "Nebelwanderung mit Thermoskanne", en: "Fog walk with a thermos"), details: LText(de: "Wartet auf den ersten richtigen Nebeltag, füllt Kakao in die Thermoskanne und nehmt genau den Feldweg, der sonst zu unspektakulär ist.", en: "Wait for the first properly foggy day, fill a thermos with cocoa, and take exactly the field path that's usually too unspectacular."), indoor: false, budget: 0, tags: ["outdoor", "cozy"]),
        DateIdea(id: 146, emoji: "🎃", title: LText(de: "Kürbis-Schnitz-Duell", en: "Pumpkin-carving duel"), details: LText(de: "Kauft zwei Kürbisse und legt 45 Minuten fest — danach entscheidet ein Foto-Vergleich, welcher von beiden auf die Treppe darf.", en: "Buy two pumpkins and set a 45-minute timer — afterwards a photo face-off decides which one earns the front step."), indoor: true, budget: 1, tags: ["creative", "silly", "athome"]),
        DateIdea(id: 147, emoji: "☕", title: LText(de: "Stammcafé-Casting", en: "Regular-café auditions"), details: LText(de: "Besucht an drei Samstagen hintereinander je ein neues Café — nach dem dritten wird feierlich euer offizielles Stammcafé gekürt.", en: "Visit one new café on each of three Saturdays in a row — after the third, solemnly crown your official regular spot."), indoor: true, budget: 2, tags: ["food", "cozy"]),
        DateIdea(id: 148, emoji: "🕯️", title: LText(de: "Stromausfall-Abend", en: "Blackout evening"), details: LText(de: "Erklärt eurer Wohnung für einen Abend den Stromausfall: nur Kerzen, keine Bildschirme, dafür Kartenspiel und Geschichten wie vor hundert Jahren.", en: "Declare a blackout in your home for one evening: candles only, no screens — just cards and stories like a hundred years ago."), indoor: true, budget: 0, tags: ["athome", "cozy", "night"]),
        DateIdea(id: 149, emoji: "📮", title: LText(de: "Postkarte an uns selbst", en: "Postcard to ourselves"), details: LText(de: "Kauft am nächsten Kiosk eine Postkarte, schreibt sie gemeinsam an euch selbst und werft sie unterwegs ein — wann sie ankommt, bleibt Überraschung.", en: "Buy a postcard at the nearest kiosk, write it to yourselves together, and drop it in a mailbox on the way — when it arrives stays a surprise."), indoor: false, budget: 1, tags: ["creative", "romantic"]),
        DateIdea(id: 150, emoji: "🛒", title: LText(de: "Fünf-Zutaten-Abendessen", en: "Five-ingredient dinner"), details: LText(de: "Geht zusammen einkaufen: genau fünf Zutaten, abwechselnd gewählt, nichts wird abgesprochen — gekocht wird, was daraus wird.", en: "Go shopping together: exactly five ingredients, chosen in turns, no coordinating — then cook whatever that turns into."), indoor: true, budget: 1, tags: ["food", "athome", "silly"]),
        DateIdea(id: 151, emoji: "🖼️", title: LText(de: "Ein-Bild-Museum", en: "One-painting museum"), details: LText(de: "Geht ins Museum mit einem einzigen Auftrag: Jeder wählt genau ein Werk, vor dem ihr zehn Minuten sitzen bleibt — danach Kuchen und Austausch.", en: "Go to the museum with a single mission: each of you picks exactly one work to sit with for ten minutes — then cake and comparing notes."), indoor: true, budget: 1, tags: ["creative", "cozy"]),
        DateIdea(id: 152, emoji: "🧤", title: LText(de: "Wintersee-Runde", en: "Winter lake loop"), details: LText(de: "Zieht euch zu warm an und lauft einmal um den See, wenn alle anderen drinnen bleiben — unterwegs teilt ihr euch ein Paar Handschuhe, jeder eine Hand.", en: "Bundle up too warmly and walk the lake loop while everyone else stays inside — sharing one pair of gloves, one hand each."), indoor: false, budget: 0, tags: ["outdoor", "romantic"]),
        DateIdea(id: 153, emoji: "🫕", title: LText(de: "Fondue-Premiere", en: "First-time fondue"), details: LText(de: "Leiht oder kauft ein kleines Fondue-Set, schneidet Brot und Gemüse und erklärt euer Esszimmer für einen Abend offiziell zur Schweiz.", en: "Borrow or buy a small fondue set, cut up bread and vegetables, and officially declare your dining table Switzerland for the night."), indoor: true, budget: 2, tags: ["food", "athome", "cozy"]),
        DateIdea(id: 154, emoji: "📻", title: LText(de: "Hörspiel im Dunkeln", en: "Audio drama in the dark"), details: LText(de: "Sucht ein Hörspiel oder einen Erzähl-Podcast aus, macht das Licht aus und hört im Dunkeln zu — Pausen sind nur für Tee erlaubt.", en: "Pick an audio drama or a storytelling podcast, turn off the lights, and listen in the dark — pauses allowed for tea only."), indoor: true, budget: 0, tags: ["athome", "cozy", "night"]),
        DateIdea(id: 155, emoji: "🌰", title: LText(de: "Maronen und Menschen gucken", en: "Chestnuts and people-watching"), details: LText(de: "Holt am Stand eine Tüte heiße Maronen, sucht eine Bank mit gutem Blick und erfindet zu drei Vorbeilaufenden je eine Lebensgeschichte.", en: "Grab a bag of hot roasted chestnuts, find a bench with a good view, and invent a life story for three passers-by."), indoor: false, budget: 1, tags: ["outdoor", "food", "silly"]),
        DateIdea(id: 156, emoji: "🧦", title: LText(de: "Kalte-Füße-Kino", en: "Cold-feet cinema"), details: LText(de: "Ein Film, eine Decke, Wärmflaschen-Service: Wer aufsteht, muss für beide Tee nachschenken — verhandelt wird vor dem Start.", en: "One movie, one blanket, hot-water-bottle service: whoever gets up refills tea for both — negotiate the rules before pressing play."), indoor: true, budget: 0, tags: ["athome", "cozy", "night"]),
        DateIdea(id: 157, emoji: "✍️", title: LText(de: "Zeile-um-Zeile-Gedicht", en: "Line-by-line poem"), details: LText(de: "Schreibt abwechselnd je eine Zeile eines Gedichts über eure Woche — kommentiert wird nichts, vorgelesen erst ganz am Ende.", en: "Take turns writing one line each of a poem about your week — no commenting, and it only gets read aloud at the very end."), indoor: true, budget: 0, tags: ["creative", "athome"]),
        DateIdea(id: 158, emoji: "🚄", title: LText(de: "Tagesticket-Abenteuer", en: "Day-ticket adventure"), details: LText(de: "Kauft ein Tagesticket für den Nahverkehr und fahrt so weit, wie es euch trägt — zurück geht es erst nach Sonnenuntergang.", en: "Buy a regional day ticket and ride as far as it carries you — no heading home until after sunset."), indoor: false, budget: 2, tags: ["adventure"]),
        DateIdea(id: 159, emoji: "🍓", title: LText(de: "Marmeladen-Manufaktur", en: "Two-person jam workshop"), details: LText(de: "Kocht aus einem Kilo Saisonobst eure erste eigene Marmelade und gestaltet ein Etikett mit eurem Paarnamen und Jahrgang.", en: "Turn a kilo of seasonal fruit into your first homemade jam and design a label with your couple name and vintage year."), indoor: true, budget: 1, tags: ["food", "creative", "athome"]),
        DateIdea(id: 160, emoji: "💌", title: LText(de: "Zettel-Versteck-Tag", en: "Hidden-notes day"), details: LText(de: "Versteckt morgens je drei kleine Zettel mit Botschaften in Jacke, Tasche und Schuh des anderen — gefunden wird über den Tag verteilt.", en: "In the morning, hide three little notes each in the other's jacket, bag, and shoe — to be discovered throughout the day."), indoor: true, budget: 0, tags: ["romantic", "silly"], energy: .quick),
        DateIdea(id: 161, emoji: "📖", title: LText(de: "Fern-Lesekreis", en: "Two-city book club"), details: LText(de: "Kauft dasselbe Buch, lest jede Woche ein Kapitel und telefoniert sonntags mit Tee — euer eigener Lesekreis für genau zwei Personen.", en: "Buy the same book, read one chapter a week, and call each Sunday with tea in hand — your own book club for exactly two."), indoor: true, budget: 1, tags: ["longdistance", "cozy"]),
        DateIdea(id: 162, emoji: "🌃", title: LText(de: "Gute-Nacht-Fenster", en: "Goodnight windows"), details: LText(de: "Stellt euch je ans Fenster, Call am Ohr, und beschreibt euch eure Straße bei Nacht — wer zuerst drei erleuchtete Fenster zählt, darf sich etwas wünschen.", en: "Stand at your windows with the call running and describe your streets at night — whoever counts three lit windows first gets to make a wish."), indoor: true, budget: 0, tags: ["longdistance", "night", "romantic"]),
        DateIdea(id: 163, emoji: "🧺", title: LText(de: "Paket-Picknick", en: "Parcel picnic"), details: LText(de: "Schickt euch gegenseitig ein Päckchen mit Snacks aus eurer Stadt und packt beide gleichzeitig im Videocall aus — Picknickdecke ist Pflicht.", en: "Mail each other a parcel of snacks from your own city and unbox them at the same time on a video call — picnic blanket required."), indoor: true, budget: 2, tags: ["longdistance", "food"]),
        DateIdea(id: 164, emoji: "🗓️", title: LText(de: "Wiedersehens-Countdown-Kalender", en: "Reunion countdown calendar"), details: LText(de: "Bastelt für die Tage bis zum Wiedersehen je einen Mini-Umschlag mit einer Nachricht — jeden Morgen wird einer geöffnet.", en: "Make one tiny envelope with a message for every day until you reunite — one gets opened each morning."), indoor: true, budget: 1, tags: ["longdistance", "creative", "romantic"]),
        DateIdea(id: 165, emoji: "🧭", title: LText(de: "Telefonspaziergang mit Wegtausch", en: "Swapped-route phone walk"), details: LText(de: "Geht gleichzeitig spazieren und lotst euch gegenseitig: Du beschreibst deine Straße, dein Schatz entscheidet an jeder Ecke, wohin du abbiegst.", en: "Walk at the same time and steer each other: you describe your street, your partner decides at every corner which way you turn."), indoor: false, budget: 0, tags: ["longdistance", "outdoor", "silly"]),
        DateIdea(id: 166, emoji: "🎬", title: LText(de: "Trailer-Abend", en: "Trailer night"), details: LText(de: "Schaut im Call fünf Filmtrailer und wählt gemeinsam den Film für euer nächstes echtes Kino-Date beim Wiedersehen.", en: "Watch five movie trailers on a call and pick together which film gets your next real cinema date when you reunite."), indoor: true, budget: 0, tags: ["longdistance", "night"]),
        DateIdea(id: 167, emoji: "🥤", title: LText(de: "Zwei-Städte-Cafétest", en: "Two-city café test"), details: LText(de: "Sucht euch je ein Café, bestellt dasselbe Getränk und verbringt eine Stunde im Videocall — wie ein Date, nur mit zwei Rechnungen.", en: "Each pick a café, order the same drink, and spend an hour on a video call — like a date, just with two separate bills."), indoor: true, budget: 1, tags: ["longdistance", "food", "cozy"]),
        DateIdea(id: 168, emoji: "🛷", title: LText(de: "Schlittentag", en: "Sledding day"), details: LText(de: "Beim ersten richtigen Schnee wird alles stehen gelassen: Schlitten schnappen, den nächsten Hügel suchen, Wettrennen fahren — Kakao danach.", en: "When the first real snow falls, drop everything: grab a sled, find the nearest hill, race each other — cocoa afterwards."), indoor: false, budget: 0, tags: ["outdoor", "silly", "adventure"]),
        DateIdea(id: 169, emoji: "🫖", title: LText(de: "Teestunde mit gutem Geschirr", en: "Tea hour with the good china"), details: LText(de: "Deckt den Tisch mit dem guten Geschirr, backt oder kauft Kekse und haltet eine echte Teestunde ab — mit Stoffserviette und ohne Eile.", en: "Set the table with the good china, bake or buy biscuits, and hold a proper tea hour — cloth napkins, zero hurry."), indoor: true, budget: 1, tags: ["cozy", "athome"]),
        DateIdea(id: 170, emoji: "🎓", title: LText(de: "Vortrags-Roulette", en: "Lecture roulette"), details: LText(de: "Sucht eine offene Abendveranstaltung — Uni, Volkshochschule, Sternwarte — zu einem Thema, von dem ihr beide nichts versteht, und geht einfach hin.", en: "Find an open evening talk — university, community college, observatory — on a topic neither of you knows anything about, and just show up."), indoor: true, budget: 1, tags: ["creative", "adventure"]),
        DateIdea(id: 171, emoji: "🔧", title: LText(de: "Reparatur-Nachmittag", en: "Repair afternoon"), details: LText(de: "Sammelt drei kaputte Dinge aus eurer Wohnung — Knopf, Fahrradlicht, wackliger Stuhl — und repariert sie gemeinsam. Danach: Belohnungspizza.", en: "Round up three broken things from your home — a button, a bike light, a wobbly chair — and fix them together. Then: reward pizza."), indoor: true, budget: 0, tags: ["athome", "creative"]),
        DateIdea(id: 172, emoji: "🎻", title: LText(de: "Kerzen-Konzert", en: "Candlelight concert"), details: LText(de: "Bucht eines dieser Kerzenlicht-Konzerte oder baut es nach: Wohnzimmer dunkel, fünfzig Teelichter, ein Album in voller Länge, kein Wort dazwischen.", en: "Book one of those candlelight concerts or recreate it: living room dark, fifty tea lights, one album front to back, no talking in between."), indoor: true, budget: 1, tags: ["romantic", "night", "athome"]),
        DateIdea(id: 173, emoji: "🥾", title: LText(de: "Drei-Dörfer-Wanderung", en: "Three-village hike"), details: LText(de: "Sucht auf der Karte drei Dörfer, deren Namen euch gefallen, und verbindet sie zu einer Route — im mittleren gibt es Mittagessen.", en: "Find three villages on the map whose names you like and link them into one route — lunch happens in the middle one."), indoor: false, budget: 1, tags: ["outdoor", "adventure"]),
        DateIdea(id: 174, emoji: "🍲", title: LText(de: "Eintopf-Sonntag", en: "Stew Sunday"), details: LText(de: "Setzt vormittags einen großen Eintopf auf und ladet niemanden ein: Der Duft gehört heute nur euch — dazu Brot, Brettspiel und Decke.", en: "Put a big stew on in the morning and invite absolutely nobody: the smell is all yours today — plus bread, a board game, and a blanket."), indoor: true, budget: 1, tags: ["food", "athome", "cozy"]),
        DateIdea(id: 175, emoji: "📷", title: LText(de: "Fotoautomaten-Pilgerfahrt", en: "Photo-booth pilgrimage"), details: LText(de: "Findet heraus, wo in eurer Stadt noch ein echter Fotoautomat steht, und pilgert hin — vier Bilder, vier Grimassen, ein Platz im Portemonnaie.", en: "Find out where your city still has a real photo booth and make the pilgrimage — four frames, four faces, one spot in the wallet."), indoor: false, budget: 1, tags: ["silly", "romantic"]),
        DateIdea(id: 176, emoji: "🌇", title: LText(de: "Feierabend am höchsten Punkt", en: "After-work high point"), details: LText(de: "Verabredet euch direkt nach der Arbeit am höchsten öffentlich erreichbaren Punkt eurer Stadt — Parkhausdeck zählt — und schaut zu, wie unten alle heimeilen.", en: "Meet right after work at the highest publicly reachable point in your city — a parking-garage roof counts — and watch everyone below hurry home."), indoor: false, budget: 0, tags: ["outdoor", "romantic"]),
        DateIdea(id: 177, emoji: "🎁", title: LText(de: "Wunschzettel-Tausch", en: "Wish-list swap"), details: LText(de: "Schreibt euch je einen Wunschzettel mit fünf kleinen Dingen unter zehn Euro und erfüllt in den nächsten zwei Wochen heimlich mindestens einen davon.", en: "Each write a wish list of five small things under ten euros — then secretly grant at least one within the next two weeks."), indoor: true, budget: 1, tags: ["romantic", "silly"]),
        DateIdea(id: 178, emoji: "🏊", title: LText(de: "Wintermorgen-Schwimmbad", en: "Winter-morning pool"), details: LText(de: "Geht an einem Wintermorgen als Erste ins Hallenbad, wenn das Wasser noch spiegelglatt ist — danach Kakao mit nassen Haaren.", en: "Be the first ones into the indoor pool on a winter morning, while the water is still mirror-flat — then cocoa with wet hair."), indoor: true, budget: 1, tags: ["adventure"]),
        DateIdea(id: 179, emoji: "🕰️", title: LText(de: "Zeitkapsel-Schuhkarton", en: "Shoebox time capsule"), details: LText(de: "Füllt einen Schuhkarton mit Kinokarten, Fotos und einem Brief, klebt ihn zu und schreibt ein Öffnungsdatum in drei Jahren darauf.", en: "Fill a shoebox with ticket stubs, photos, and a letter, tape it shut, and write an opening date three years from now on the lid."), indoor: true, budget: 0, tags: ["creative", "romantic", "athome"]),
        DateIdea(id: 180, emoji: "🍽️", title: LText(de: "Bestell für mich", en: "Order for me"), details: LText(de: "Geht essen und bestellt komplett füreinander — Getränk, Hauptgang, Dessert. Über die Wahl geredet wird erst, wenn die Teller da sind.", en: "Go out and order entirely for each other — drink, main, dessert. No discussing the choices until the plates arrive."), indoor: true, budget: 2, tags: ["food", "silly"]),
        DateIdea(id: 181, emoji: "🌨️", title: LText(de: "Erster-Schnee-Pakt", en: "First-snow pact"), details: LText(de: "Schließt heute den Pakt: Beim ersten Schnee des Winters lasst ihr alles stehen und geht sofort zehn Minuten raus — egal wie ungelegen es kommt.", en: "Make the pact today: at the winter's first snowfall you drop everything and step outside for ten minutes — no matter how inconvenient."), indoor: false, budget: 0, tags: ["outdoor", "romantic", "silly"]),
        DateIdea(id: 182, emoji: "🎹", title: LText(de: "Offenes-Klavier-Suche", en: "Public-piano quest"), details: LText(de: "Findet das nächste öffentliche Klavier — Bahnhof, Flughafen, Einkaufszentrum — und spielt vierhändig irgendetwas. Können ist optional, Mut zählt.", en: "Track down the nearest public piano — train station, airport, mall — and play something four-handed. Skill optional, courage mandatory."), indoor: false, budget: 0, tags: ["adventure", "silly", "creative"]),
        // Expansion 3 — Lebensrealitäten.
        // 183–192: wenig Zeit / erschöpft (≤ 20 Minuten, energy .quick).
        DateIdea(id: 183, emoji: "🕯️", title: LText(de: "Zwanzig-Minuten-Urlaub", en: "Twenty-minute vacation"), details: LText(de: "Handys in den Flugmodus, Timer auf zwanzig Minuten: ein Getränk, eine Decke und ein Thema, das nichts mit Alltag zu tun hat.", en: "Phones on airplane mode, a twenty-minute timer: one drink, one blanket, and one topic that has nothing to do with daily life."), indoor: true, budget: 0, tags: ["cozy", "athome"], energy: .quick),
        DateIdea(id: 184, emoji: "🍫", title: LText(de: "Ein-Pralinen-Date", en: "One-chocolate date"), details: LText(de: "Kauft eine einzige richtig gute Praline oder ein Stück Kuchen, teilt es mit zwei Gabeln und erzählt euch dabei das Beste vom Tag.", en: "Buy one single properly good chocolate or slice of cake, share it with two forks, and trade the best part of your day over it."), indoor: true, budget: 1, tags: ["food", "cozy"], energy: .quick),
        DateIdea(id: 185, emoji: "💃", title: LText(de: "Drei-Songs-Tanz", en: "Three-song dance"), details: LText(de: "Genau drei Songs lang tanzen: einer albern, einer eng, einen wählt der Zufallsmodus — danach seid ihr offiziell entlassen.", en: "Dance for exactly three songs: one silly, one close, one on shuffle — after that you're officially dismissed."), indoor: true, budget: 0, tags: ["silly", "athome"], energy: .quick),
        DateIdea(id: 186, emoji: "🌬️", title: LText(de: "Fünf Minuten Abendluft", en: "Five minutes of evening air"), details: LText(de: "Stellt euch fünf Minuten ans offene Fenster oder vor die Haustür, atmet durch und sagt je eine Sache, die morgen leichter wird.", en: "Stand at the open window or outside the front door for five minutes, breathe, and each name one thing that gets easier tomorrow."), indoor: false, budget: 0, tags: ["cozy", "romantic"], energy: .quick),
        DateIdea(id: 187, emoji: "📖", title: LText(de: "Ein-Kapitel-Ritual", en: "One-chapter ritual"), details: LText(de: "Lest im Bett genau ein Kapitel oder eine Kurzgeschichte laut vor — wer zuerst gähnt, macht das Licht aus.", en: "Read exactly one chapter or short story aloud in bed — whoever yawns first turns off the light."), indoor: true, budget: 0, tags: ["cozy", "athome", "night"], energy: .quick),
        DateIdea(id: 188, emoji: "⏱️", title: LText(de: "Neunzig-Sekunden-Rückblick", en: "Ninety-second recap"), details: LText(de: "Kocht ein schnelles Heißgetränk und gebt euch je neunzig Sekunden für Highlight und Tiefpunkt des Tages — der Timer läuft mit.", en: "Make a quick hot drink and give each other ninety seconds for the day's high and low — timer running."), indoor: true, budget: 0, tags: ["cozy", "athome"], energy: .quick),
        DateIdea(id: 189, emoji: "🍜", title: LText(de: "Wohnzimmerboden-Picknick", en: "Living-room floor picnic"), details: LText(de: "Kocht Instant-Nudeln, legt eine Decke aufs Wohnzimmerparkett und tut zwanzig Minuten lang so, als wärt ihr unterwegs.", en: "Cook instant noodles, spread a blanket on the living-room floor, and spend twenty minutes pretending you're somewhere far away."), indoor: true, budget: 0, tags: ["food", "athome", "silly"], energy: .quick),
        DateIdea(id: 190, emoji: "💆", title: LText(de: "Mini-Massage-Tausch", en: "Mini massage swap"), details: LText(de: "Fragt euch: Lust auf je sieben Minuten Schultern oder Hände? Bei zwei Mal Ja wünscht sich, wer dran ist, Stelle und Druck. Danach wird nichts mehr erledigt, versprochen.", en: "Ask each other: up for seven minutes each of shoulders or hands? Two yeses, and whoever's turn it is picks the spot and the pressure. No chores afterwards, promise."), indoor: true, budget: 0, tags: ["cozy", "romantic", "athome"], energy: .quick),
        DateIdea(id: 191, emoji: "📺", title: LText(de: "Eine-Folge-Abend", en: "One-episode night"), details: LText(de: "Eine einzige Folge eurer Serie, aber richtig: Snacks, Decke, Handys außer Reichweite — und der Rest der Nacht gehört dem Schlaf.", en: "One single episode of your show, done properly: snacks, blanket, phones out of reach — and the rest of the night belongs to sleep."), indoor: true, budget: 0, tags: ["cozy", "athome", "night"], energy: .quick),
        DateIdea(id: 192, emoji: "📝", title: LText(de: "Kühlschrank-Post", en: "Fridge mail"), details: LText(de: "Schreibt euch je eine Haftnotiz für morgen früh an den Kühlschrank — Thema frei, Herzchen erlaubt.", en: "Each leave a sticky note on the fridge for tomorrow morning — any topic, hearts allowed."), indoor: true, budget: 0, tags: ["romantic", "athome", "silly"], energy: .quick),
        // 193–202: kleine Wohnung, kein Balkon, kein Auto.
        DateIdea(id: 193, emoji: "🪙", title: LText(de: "Haustür-Lotterie", en: "Front-door lottery"), details: LText(de: "Werft an der Haustür eine Münze: Kopf heißt links, Zahl heißt rechts — nach zwanzig Minuten nehmt ihr den direkten Heimweg.", en: "Flip a coin at your front door: heads means left, tails means right — after twenty minutes take the straight route home."), indoor: false, budget: 0, tags: ["outdoor", "adventure"], energy: .quick),
        DateIdea(id: 194, emoji: "🪑", title: LText(de: "Reservierung am eigenen Tisch", en: "Reservation at your own table"), details: LText(de: "Verwandelt euren Tisch in ein Restaurant: handgeschriebene Karte, Kerze, feste Reservierungszeit — der Weg dorthin führt einmal ums Haus.", en: "Turn your own table into a restaurant: handwritten menu, candle, a firm reservation time — the way there leads once around the block."), indoor: true, budget: 1, tags: ["food", "athome", "romantic"]),
        DateIdea(id: 195, emoji: "🧺", title: LText(de: "Waschsalon-Date", en: "Laundromat date"), details: LText(de: "Wenn die Wohnung keinen Platz für Programm lässt: Nehmt die große Wäsche mit in den Waschsalon — dazu geteilte Kopfhörer, ein Hörspiel und Automaten-Snacks.", en: "When your flat is too small for plans: take the big laundry load to the laundromat — with shared earbuds, an audio drama, and vending-machine snacks."), indoor: true, budget: 1, tags: ["silly", "adventure"]),
        DateIdea(id: 196, emoji: "🌳", title: LText(de: "Parkbank-Abendessen", en: "Park-bench dinner"), details: LText(de: "Holt euch etwas auf die Hand und esst es auf der schönsten Bank im Umkreis von zehn Gehminuten — Abendlicht ist der Bonus.", en: "Grab something to eat on the go and have it on the prettiest bench within ten minutes' walk — evening light is the bonus."), indoor: false, budget: 1, tags: ["outdoor", "food"]),
        DateIdea(id: 197, emoji: "🖼️", title: LText(de: "Fensterbank-Galerie", en: "Windowsill gallery"), details: LText(de: "Baut eure Fensterbank zur Mini-Galerie um: drei gerahmte Fotos von euch, feierliche Eröffnung mit Saft im Sektglas.", en: "Turn your windowsill into a tiny gallery: three framed photos of you two, grand opening with juice in champagne glasses."), indoor: true, budget: 1, tags: ["creative", "athome"]),
        DateIdea(id: 198, emoji: "🛋️", title: LText(de: "Ein-Möbel-Revolution", en: "One-furniture revolution"), details: LText(de: "Stellt gemeinsam genau ein Möbelstück um und feiert, wie neu sich die Wohnung anfühlt — Probeliegen inklusive.", en: "Move exactly one piece of furniture together and celebrate how new the whole place feels — test-lounging included."), indoor: true, budget: 0, tags: ["athome", "creative"]),
        DateIdea(id: 199, emoji: "🚇", title: LText(de: "Öffi-Safari", en: "Transit safari"), details: LText(de: "Eine Tageskarte, keine Ziele mit Namen: Steigt dreimal irgendwo aus, wo ihr noch nie wart — der dritte Halt entscheidet, wo es Kaffee gibt.", en: "One day pass, no named destinations: get off three times somewhere you've never been — the third stop decides where coffee happens."), indoor: false, budget: 1, tags: ["adventure"]),
        DateIdea(id: 200, emoji: "🏛️", title: LText(de: "Eintritt-frei-Tag", en: "Free-admission day"), details: LText(de: "Sucht heraus, was eure Stadt gratis hergibt — Museumsabende, Bibliothek, offene Kirchen — und baut daraus euer Null-Euro-Date.", en: "Find out what your city gives away for free — museum nights, the library, open churches — and build your zero-euro date from that."), indoor: true, budget: 0, tags: ["creative", "adventure"]),
        DateIdea(id: 201, emoji: "🥇", title: LText(de: "Ein-Quadratmeter-Olympiade", en: "One-square-meter olympics"), details: LText(de: "Fünf Disziplinen, die auf einen Quadratmeter passen: Socken-Weitwurf, Münzen-Stapeln, Luftanhalten und mehr — Siegerehrung auf dem Sofa.", en: "Five events that fit in one square meter: sock toss, coin stacking, breath holding, and more — medal ceremony on the couch."), indoor: true, budget: 0, tags: ["silly", "athome"]),
        DateIdea(id: 202, emoji: "🌿", title: LText(de: "Fensterbrett-Garten", en: "Windowsill garden"), details: LText(de: "Kauft zwei Töpfe Küchenkräuter fürs Fensterbrett — jeder übernimmt die Patenschaft für einen, und in vier Wochen kocht ihr das erste Gericht damit.", en: "Buy two pots of kitchen herbs for the windowsill — each of you adopts one, and in four weeks you cook your first dish with them."), indoor: true, budget: 1, tags: ["creative", "athome", "food"]),
        // 203–212: eingeschränkte Mobilität.
        DateIdea(id: 203, emoji: "🗺️", title: LText(de: "Weltreise vom Sofa", en: "World tour from the couch"), details: LText(de: "Wählt ein Land, kocht oder bestellt passend, dazu Musik und eine Doku von dort — der Reisepass bleibt in der Schublade.", en: "Pick a country, cook or order to match, add its music and a documentary — passports stay in the drawer."), indoor: true, budget: 1, tags: ["athome", "food", "creative"]),
        DateIdea(id: 204, emoji: "🔭", title: LText(de: "Fenster-Vogelkunde", en: "Window birdwatching"), details: LText(de: "Hängt Futter vors Fenster oder beobachtet einfach: Wer entdeckt in einer Woche die meisten Vogelarten? Die Strichliste hängt am Kühlschrank.", en: "Hang up a feeder or simply watch: who spots more bird species in a week? The tally sheet lives on the fridge."), indoor: true, budget: 1, tags: ["creative", "cozy", "athome"]),
        DateIdea(id: 205, emoji: "🎙️", title: LText(de: "Interview fürs Archiv", en: "Interview for the archive"), details: LText(de: "Nehmt euch gegenseitig ein Lebensinterview auf — Kindheit, erste Liebe, größter Zufall. Eine Aufnahme pro Abend, aufgehoben für später.", en: "Record a life interview with each other — childhood, first love, biggest coincidence. One recording per evening, kept for later."), indoor: true, budget: 0, tags: ["creative", "athome", "cozy"]),
        DateIdea(id: 206, emoji: "🏆", title: LText(de: "Dauerturnier mit Tabelle", en: "Standing tournament"), details: LText(de: "Startet ein Dauerturnier in eurem Lieblingsspiel: Jede Partie zählt, die Tabelle hängt an der Wand, das Finale bekommt ein Buffet.", en: "Start a standing tournament in your favorite game: every match counts, the league table hangs on the wall, the final gets a buffet."), indoor: true, budget: 0, tags: ["athome", "silly"]),
        DateIdea(id: 207, emoji: "🖌️", title: LText(de: "Vier-Hände-Bild", en: "Four-hands painting"), details: LText(de: "Ein großes Blatt, zwei Stifte, keine Absprache: Malt gleichzeitig an einem Bild, bis es fertig ist — der Titel wird gemeinsam vergeben.", en: "One big sheet, two pens, no coordinating: draw on the same picture at the same time until it's done — then title it together."), indoor: true, budget: 0, tags: ["creative", "athome"]),
        DateIdea(id: 208, emoji: "🧭", title: LText(de: "Street-View-Kindheitstour", en: "Street View childhood tour"), details: LText(de: "Besucht per Street View die Orte eurer Kindheit und führt euch gegenseitig herum: Schulweg, Lieblingsversteck, erster Kuss.", en: "Visit your childhood places on Street View and give each other the tour: school route, favorite hiding spot, first kiss."), indoor: true, budget: 0, tags: ["creative", "cozy", "athome"]),
        DateIdea(id: 209, emoji: "🍪", title: LText(de: "Backstube mit Pausen", en: "Bakery with breaks"), details: LText(de: "Backt etwas, das Pausen verzeiht: Teig am Tisch kneten, die Ofenzeit für das, worauf ihr beide Lust habt — Kuscheln inklusive, wenn ihr beide mögt — und das warme Ergebnis fürs Sofa.", en: "Bake something forgiving: knead the dough at the table, spend the oven time however you both like — cuddling included, if you're both in the mood — and take the warm result to the couch."), indoor: true, budget: 1, tags: ["food", "athome", "cozy"]),
        DateIdea(id: 210, emoji: "🎧", title: LText(de: "Nur-zusammen-Hörbuch", en: "Only-together audiobook"), details: LText(de: "Startet ein Hörbuch, das ihr ausschließlich gemeinsam weiterhören dürft — Verstöße kosten den Kuchen fürs Wochenende.", en: "Start an audiobook you're only allowed to continue together — violations cost the weekend cake."), indoor: true, budget: 0, tags: ["cozy", "athome"]),
        DateIdea(id: 211, emoji: "📌", title: LText(de: "Erinnerungswand", en: "Memory wall"), details: LText(de: "Sortiert eine Handvoll Fotos, Tickets und Zettel und gestaltet eine kleine Erinnerungswand — jeden Monat kommt ein neues Stück dazu.", en: "Sort a handful of photos, tickets, and notes into a small memory wall — one new piece gets added every month."), indoor: true, budget: 1, tags: ["creative", "athome", "romantic"]),
        DateIdea(id: 212, emoji: "🃏", title: LText(de: "Neues-Spiel-Abend", en: "New-game night"), details: LText(de: "Lernt gemeinsam die Regeln eines Spiels, das ihr beide noch nie gespielt habt — die erste Partie zählt traditionell nicht.", en: "Learn the rules of a game neither of you has ever played — by tradition, the first round doesn't count."), indoor: true, budget: 1, tags: ["athome", "silly", "cozy"]),
        // 213–222: Schichtarbeit & asynchrone Zeiten.
        DateIdea(id: 213, emoji: "📓", title: LText(de: "Staffel-Tagebuch", en: "Relay journal"), details: LText(de: "Ein Notizbuch auf dem Küchentisch: Wer heimkommt, schreibt drei Zeilen — wer aufwacht, antwortet. Euer Gespräch läuft weiter, nur zeitversetzt.", en: "One notebook on the kitchen table: whoever comes home writes three lines — whoever wakes up replies. Your conversation keeps going, just time-shifted."), indoor: true, budget: 0, tags: ["romantic", "athome", "creative"], energy: .quick),
        DateIdea(id: 214, emoji: "🍱", title: LText(de: "Herzens-Lunchbox", en: "Sweetheart lunchbox"), details: LText(de: "Pack deinem Schatz für die nächste Schicht eine kleine Box — mit einem Zettel, der erst in der Pause gelesen werden darf.", en: "Pack a small box for your sweetheart's next shift — with a note that may only be read on break."), indoor: true, budget: 1, tags: ["food", "romantic"], energy: .quick),
        DateIdea(id: 215, emoji: "🌅", title: LText(de: "Feierabend um sechs Uhr früh", en: "Quitting time at 6 a.m."), details: LText(de: "Wenn die Nachtschicht endet: Frühstück, serviert wie ein Abendessen — Kerze an, Wein durch Kaffee ersetzt, angestoßen wird auf den Feierabend.", en: "When the night shift ends: breakfast served like dinner — candle lit, wine swapped for coffee, a toast to quitting time."), indoor: true, budget: 1, tags: ["food", "athome", "romantic"]),
        DateIdea(id: 216, emoji: "📸", title: LText(de: "Tag-und-Nacht-Staffel", en: "Day-and-night relay"), details: LText(de: "Jede wache Stunde ein Foto in den Chat: Einer sammelt den Tag, einer die Nacht — am freien Tag schaut ihr beide Filme zusammen.", en: "One photo to the chat for every waking hour: one of you collects the day, the other the night — on your day off you watch both films together."), indoor: true, budget: 0, tags: ["creative", "silly"]),
        DateIdea(id: 217, emoji: "🫖", title: LText(de: "Überlappungs-Viertelstunde", en: "Overlap quarter hour"), details: LText(de: "Findet die fünfzehn Minuten, in denen ihr beide wach und zuhause seid, und erklärt sie zur festen Kakao-Zeit — gleiche Stelle, jeden Tag.", en: "Find the fifteen minutes when you're both awake and home, and declare them standing cocoa time — same spot, every day."), indoor: true, budget: 0, tags: ["cozy", "athome"], energy: .quick),
        DateIdea(id: 218, emoji: "🫕", title: LText(de: "Abendessen im Kühlschrank", en: "Dinner in the fridge"), details: LText(de: "Koch doppelt und stell die zweite Portion mit Anrichte-Anleitung und Liebesgruß in den Kühlschrank — Fernkochen für die Spätschicht.", en: "Cook a double batch and leave the second plate in the fridge with plating instructions and a love note — remote cooking for the late shift."), indoor: true, budget: 1, tags: ["food", "athome"], energy: .quick),
        DateIdea(id: 219, emoji: "🌙", title: LText(de: "Mond-Verabredung", en: "Moon appointment"), details: LText(de: "Verabredet euch mit dem Mond: Wer ihn zuerst sieht, schickt ein Foto — der andere antwortet, sobald er dran ist. Gleicher Mond, verschobene Stunden.", en: "Make a date with the moon: whoever sees it first sends a photo — the other replies when it's their turn. Same moon, shifted hours."), indoor: false, budget: 0, tags: ["romantic", "night"], energy: .quick),
        DateIdea(id: 220, emoji: "📻", title: LText(de: "Einschlaf-Radio füreinander", en: "Bedtime radio for each other"), details: LText(de: "Nehmt euch gegenseitig fünf Minuten Einschlaf-Radio auf: ein Tagesrückblick, ein gesummtes Lied, ein Gute-Nacht-Satz — abspielbar, wann immer die Nacht beginnt.", en: "Record each other five minutes of bedtime radio: a recap, a hummed song, a goodnight line — playable whenever the night starts."), indoor: true, budget: 0, tags: ["cozy", "romantic", "night"], energy: .quick),
        DateIdea(id: 221, emoji: "🥞", title: LText(de: "Dienstags-Sonntag", en: "Tuesday Sunday"), details: LText(de: "Euer gemeinsamer freier Tag ist euer Sonntag — auch wenn er auf einen Dienstag fällt: Pancakes, langes Frühstück, keine Termine.", en: "Your shared day off is your Sunday — even when it lands on a Tuesday: pancakes, a long breakfast, zero appointments."), indoor: true, budget: 1, tags: ["food", "athome", "cozy"]),
        DateIdea(id: 222, emoji: "💌", title: LText(de: "Kopfkissen-Post", en: "Pillow mail"), details: LText(de: "Wer zuerst aus dem Haus muss, legt dem anderen etwas aufs Kopfkissen: ein Bonbon, ein Foto, zwei Sätze — kleine Post zwischen zwei Zeitzonen unter einem Dach.", en: "Whoever leaves first puts something on the other's pillow: a sweet, a photo, two sentences — little mail between two time zones under one roof."), indoor: true, budget: 0, tags: ["romantic", "athome"], energy: .quick),
        // 223+: Mega-Welle. Block 1 — Null-Budget zuhause.
        DateIdea(id: 223, emoji: "🗄️", title: LText(de: "Schubladen-Archäologie", en: "Junk-drawer archaeology"), details: LText(de: "Öffnet gemeinsam die eine Schublade, in der alles landet. Jeder Fund bekommt seine Geschichte erzählt — und ein Urteil: Museum, Müll oder Ehrenplatz.", en: "Open the one drawer where everything ends up. Every find gets its story told — and a verdict: museum, bin, or place of honor."), indoor: true, budget: 0, tags: ["silly", "athome"], energy: .quick),
        DateIdea(id: 224, emoji: "✍️", title: LText(de: "Falsche-Hand-Briefe", en: "Wrong-hand letters"), details: LText(de: "Schreibt euch kurze Liebesbotschaften mit der falschen Hand — und entziffert sie gemeinsam. Das Ergebnis darf gerahmt werden.", en: "Write each other short love notes with your non-dominant hand — then decipher them together. Framing the results is allowed."), indoor: true, budget: 0, tags: ["silly", "creative", "athome"], energy: .quick),
        DateIdea(id: 225, emoji: "🎭", title: LText(de: "Drei-Gegenstände-Theater", en: "Three-prop theater"), details: LText(de: "Greift euch drei zufällige Gegenstände aus der Wohnung und spielt damit die Szene nach, wie ihr euch kennengelernt habt — Requisiten sind Pflicht.", en: "Grab three random objects from around your home and reenact the scene of how you met — props are mandatory."), indoor: true, budget: 0, tags: ["silly", "creative", "athome"]),
        DateIdea(id: 226, emoji: "🏠", title: LText(de: "Zuhause-Quiz", en: "Home-turf quiz"), details: LText(de: "Wer kennt eure Wohnung besser? Wie viele Fenster, was liegt ganz hinten im Gefrierfach, welche Farbe hat das Badregal — stellt euch abwechselnd Fragen.", en: "Who knows your home better? How many windows, what's at the back of the freezer, what color is the bathroom shelf — take turns quizzing each other."), indoor: true, budget: 0, tags: ["silly", "athome"], energy: .quick),
        DateIdea(id: 227, emoji: "🔤", title: LText(de: "Komplimente-Alphabet", en: "Compliment alphabet"), details: LText(de: "Von A bis Z, immer abwechselnd: ein Kompliment mit dem nächsten Buchstaben. Bei Q und X darf gedichtet werden.", en: "From A to Z, taking turns: one compliment per letter. Poetic license is granted for Q and X."), indoor: true, budget: 0, tags: ["romantic", "athome"], energy: .quick),
        DateIdea(id: 228, emoji: "🌬️", title: LText(de: "Atem-Duett", en: "Breathing duet"), details: LText(de: "Wenn ihr beide mögt: Legt euch Rücken an Brust und lasst euren Atem zehn Minuten denselben Takt finden. Kein Ziel, kein Gespräch — nur Ankommen.", en: "If you're both up for it: lie back to chest and let your breathing find the same rhythm for ten minutes. No goal, no talking — just arriving."), indoor: true, budget: 0, tags: ["cozy", "romantic", "athome"], energy: .quick),
        DateIdea(id: 229, emoji: "🪴", title: LText(de: "Zimmerpflanzen-Taufe", en: "Houseplant christening"), details: LText(de: "Gebt jeder Pflanze in eurer Wohnung feierlich einen Namen und eine Biografie. Die Monstera hat mehr erlebt, als ihr denkt.", en: "Solemnly give every plant in your home a name and a backstory. The monstera has seen more than you think."), indoor: true, budget: 0, tags: ["silly", "athome"], energy: .quick),
        DateIdea(id: 230, emoji: "📜", title: LText(de: "Dramatische Chat-Lesung", en: "Dramatic chat reading"), details: LText(de: "Scrollt an den Anfang eures Chatverlaufs und lest eure ersten Nachrichten laut vor — mit Theaterstimme, Kunstpausen und Publikumskommentar.", en: "Scroll to the very start of your chat history and read your first messages aloud — stage voice, dramatic pauses, audience commentary included."), indoor: true, budget: 0, tags: ["silly", "romantic", "athome"]),
        DateIdea(id: 231, emoji: "🫙", title: LText(de: "Gewürz-Riechprobe", en: "Spice-rack smell test"), details: LText(de: "Augen zu, Gewürzregal auf: Wer errät mehr Gewürze nur am Geruch? Der Verlierer würzt eine Woche lang nach Ansage.", en: "Eyes closed, spice rack open: who can name more spices by smell alone? The loser seasons on command for a week."), indoor: true, budget: 0, tags: ["food", "silly", "athome"], energy: .quick),
        DateIdea(id: 232, emoji: "🎬", title: LText(de: "Trailer-Stimme fürs Fotoalbum", en: "Trailer voice-over album"), details: LText(de: "Blättert durch alte Fotos und vertont sie als Kino-Trailer: In einer Welt, in der zwei Menschen sich ein Sofa teilen …", en: "Flip through old photos and narrate them like a movie trailer: In a world where two people share one couch …"), indoor: true, budget: 0, tags: ["silly", "creative", "athome"]),
        DateIdea(id: 233, emoji: "🧷", title: LText(de: "Zukunfts-Moodboard", en: "Future moodboard"), details: LText(de: "Alte Zeitschriften, Schere, Kleber: Bastelt eine Collage von eurem nächsten Jahr. Was draufklebt, zählt als beantragt.", en: "Old magazines, scissors, glue: collage your next year together. Whatever makes it onto the board counts as officially requested."), indoor: true, budget: 0, tags: ["creative", "athome"]),
        DateIdea(id: 234, emoji: "📐", title: LText(de: "Traum-Grundriss", en: "Dream floor plan"), details: LText(de: "Zeichnet auf ein großes Blatt den Grundriss eurer Traumwohnung — inklusive der unvernünftigen Wünsche: Rutsche, Bibliothek, Katzenzimmer.", en: "Sketch the floor plan of your dream home on one big sheet — unreasonable wishes included: slide, library, cat room."), indoor: true, budget: 0, tags: ["creative", "athome"]),
        DateIdea(id: 235, emoji: "🥇", title: LText(de: "Erste-Male-Liste", en: "List of firsts"), details: LText(de: "Sammelt alle ersten Male, die ihr schon hattet — vom ersten Lachen bis zur ersten Panne. Dann wählt das nächste erste Mal aus.", en: "Collect every first the two of you have already had — first laugh to first mishap. Then pick your next first."), indoor: true, budget: 0, tags: ["romantic", "athome"], energy: .quick),
        DateIdea(id: 236, emoji: "🔄", title: LText(de: "Gegenteil-Abend", en: "Opposite evening"), details: LText(de: "Tauscht für einen Abend die Seiten: Bettseite, Sofaplatz, Lieblingstasse, Standardsätze. Wer zuerst aus der Rolle fällt, macht den Abwasch.", en: "Swap sides for one evening: bed side, couch spot, favorite mug, signature phrases. First to break character does the dishes."), indoor: true, budget: 0, tags: ["silly", "athome"]),
        DateIdea(id: 237, emoji: "☕", title: LText(de: "Küchen-Barista", en: "Kitchen barista"), details: LText(de: "Eröffnet euer eigenes Café: Einer nimmt die Bestellung auf, der andere zaubert mit Bordmitteln — aufgeschäumte Milch, Zimt, Kakao-Herz. Trinkgeld in Küssen.", en: "Open your own café: one takes the order, the other improvises with pantry supplies — frothed milk, cinnamon, a cocoa heart. Tips accepted in kisses."), indoor: true, budget: 0, tags: ["food", "cozy", "athome"], energy: .quick),
        DateIdea(id: 238, emoji: "🤵", title: LText(de: "Pyjama-Gala", en: "Pajama gala"), details: LText(de: "Dresscode: oben festlich, unten Schlafanzug. Deckt feierlich den Tisch, haltet Tischreden und verleiht euch gegenseitig Preise für das vergangene Jahr.", en: "Dress code: formal on top, pajamas below. Set the table ceremoniously, give dinner speeches, and present each other awards for the past year."), indoor: true, budget: 0, tags: ["silly", "romantic", "athome"]),
        DateIdea(id: 239, emoji: "🖐️", title: LText(de: "Schattentheater an der Wand", en: "Hand-shadow theater"), details: LText(de: "Eine Lampe, eine weiße Wand, vier Hände: Erzählt eure Kennenlerngeschichte als Schattenspiel. Der Hund aus zwei Händen ist Pflichtbesetzung.", en: "One lamp, one blank wall, four hands: tell the story of how you met as a shadow play. The two-hand dog is a mandatory cast member."), indoor: true, budget: 0, tags: ["creative", "silly", "athome"], energy: .quick),
        DateIdea(id: 240, emoji: "🙈", title: LText(de: "Blind durch die Wohnung", en: "Blindfolded home tour"), details: LText(de: "Wer mag, schließt die Augen und lässt sich vom anderen behutsam durch die Wohnung führen — an Geräuschen, Düften und Oberflächen entlang. Danach wird getauscht, wenn ihr beide wollt.", en: "If you like, close your eyes and let your partner gently guide you through your home — by sounds, scents, and textures. Then switch, if you both want to."), indoor: true, budget: 0, tags: ["adventure", "cozy", "athome"], energy: .quick),
        // Block 2 — Fernbeziehung / Video-Call.
        DateIdea(id: 241, emoji: "🧩", title: LText(de: "Kreuzworträtsel im Duett", en: "Crossword duet"), details: LText(de: "Druckt dasselbe Kreuzworträtsel aus oder öffnet es online und löst es gemeinsam im Call — einer liest vor, beide raten, keiner googelt. Fast keiner.", en: "Print or open the same crossword and solve it together on a call — one reads the clues, both guess, nobody googles. Almost nobody."), indoor: true, budget: 0, tags: ["cozy", "longdistance"], energy: .quick),
        DateIdea(id: 242, emoji: "☁️", title: LText(de: "Wolken-Wette", en: "Cloud bet"), details: LText(de: "Beide raus vor die Tür, Blick nach oben: Wer findet in fünf Minuten die beste Wolkenform? Beweisfotos in den Chat, der Gewinner bestimmt das nächste Telefonthema.", en: "Both of you step outside and look up: who spots the best cloud shape in five minutes? Photo evidence in the chat — winner picks the next call's topic."), indoor: false, budget: 0, tags: ["silly", "outdoor", "longdistance"], energy: .quick),
        DateIdea(id: 243, emoji: "🪙", title: LText(de: "Ein-Euro-Duell", en: "One-euro duel"), details: LText(de: "Jeder kauft bis zum nächsten Call das beste Ding für maximal einen Euro. Die Enthüllung wird zelebriert, die Jury seid ihr selbst.", en: "Before the next call, each of you buys the best thing one euro can get. Celebrate the reveal — you two are the jury."), indoor: true, budget: 1, tags: ["silly", "longdistance"], energy: .quick),
        DateIdea(id: 244, emoji: "🏢", title: LText(de: "Makler-Führung per Video", en: "Realtor video tour"), details: LText(de: "Führt euch gegenseitig per Video durch die eigene Wohnung — als übertrieben begeisterte Immobilienmakler: lichtdurchflutet, zentrale Lage, Blick ins Grüne (die Topfpflanze).", en: "Give each other a video tour of your own place — as wildly enthusiastic real-estate agents: flooded with light, prime location, garden views (the potted plant)."), indoor: true, budget: 0, tags: ["silly", "longdistance"]),
        DateIdea(id: 245, emoji: "🗺️", title: LText(de: "Fern-Schnitzeljagd", en: "Remote scavenger hunt"), details: LText(de: "Einer spaziert mit Video-Call, der andere gibt Suchaufträge: etwas Rotes, ein schöner Baum, die freundlichste Haustür. Rollen tauschen nicht vergessen.", en: "One walks with the video call running, the other sets the scavenger tasks: something red, a beautiful tree, the friendliest front door. Don't forget to swap roles."), indoor: false, budget: 0, tags: ["adventure", "outdoor", "longdistance"]),
        DateIdea(id: 246, emoji: "📞", title: LText(de: "Anruf aus dem Jahr 2050", en: "Call from the year 2050"), details: LText(de: "Ruft euch an, als wärt ihr im Jahr 2050: Erzählt, wie alles gekommen ist — das Haus, die Reisen, der legendäre Streit über die Spülmaschine. Bleibt konsequent in der Rolle.", en: "Call each other as if it's 2050: report how everything turned out — the house, the trips, the legendary dishwasher argument. Stay in character."), indoor: true, budget: 0, tags: ["silly", "romantic", "longdistance"], energy: .quick),
        DateIdea(id: 247, emoji: "🛵", title: LText(de: "Überkreuz-Lieferdienst", en: "Crisscross delivery"), details: LText(de: "Bestellt euch gegenseitig heimlich das Abendessen an die jeweilige Haustür — jeder wählt für den anderen. Gegessen wird zusammen im Call.", en: "Secretly order dinner to each other's door — each of you chooses for the other. Then eat together on the call."), indoor: true, budget: 2, tags: ["food", "longdistance"]),
        DateIdea(id: 248, emoji: "🏇", title: LText(de: "Briefe-Wettrennen", en: "Letter race"), details: LText(de: "Gebt am selben Tag je einen Brief auf und wettet, welcher zuerst ankommt. Der Sieger-Brief wird im Call feierlich zuerst vorgelesen.", en: "Mail one letter each on the same day and bet on which arrives first. The winning letter gets read aloud first, with full ceremony, on the call."), indoor: true, budget: 1, tags: ["romantic", "longdistance"]),
        DateIdea(id: 249, emoji: "🕰️", title: LText(de: "Drei Dinge von früher", en: "Three things from before"), details: LText(de: "Zeigt euch im Call je drei Gegenstände, die älter sind als eure Beziehung — und erzählt, wer ihr wart, als sie neu waren.", en: "On the call, each of you shows three objects older than your relationship — and tells who you were when they were new."), indoor: true, budget: 0, tags: ["cozy", "longdistance"], energy: .quick),
        DateIdea(id: 250, emoji: "🧮", title: LText(de: "Puzzle-Fernduell", en: "Long-distance puzzle race"), details: LText(de: "Kauft dasselbe Puzzle und legt los: Wer zuerst fertig ist, gewinnt — Fortschrittsfotos sind Pflicht, Schummeln wird romantisch geahndet.", en: "Buy the same jigsaw and go: first to finish wins — progress photos are mandatory, and cheating is punished romantically."), indoor: true, budget: 1, tags: ["cozy", "longdistance"]),
        // Block 3 — Jahreszeiten-Specials.
        DateIdea(id: 251, emoji: "🌸", title: LText(de: "Blütenregen-Runde", en: "Blossom-rain walk"), details: LText(de: "Sucht in eurer Gegend die am schönsten blühenden Bäume und lasst euch unter dem besten fotografieren — jedes Jahr wieder, gleicher Baum.", en: "Find the best blossoming trees in your area and take a photo under the finest one — same tree, every year, forever."), indoor: false, budget: 0, tags: ["outdoor", "romantic"], energy: .quick),
        DateIdea(id: 252, emoji: "🧹", title: LText(de: "Frühjahrsputz mit Endgegner", en: "Spring cleaning boss fight"), details: LText(de: "Erklärt die schlimmste Ecke der Wohnung zum Endgegner: laute Musik, Timer, klare Rollen. Nach dem Sieg gibt es ein Ritterschlag-Abendessen.", en: "Declare the worst corner of your home the final boss: loud music, a timer, clear roles. Victory earns you a knighthood dinner."), indoor: true, budget: 0, tags: ["silly", "athome"]),
        DateIdea(id: 253, emoji: "🍓", title: LText(de: "Erdbeerfeld-Ernte", en: "Strawberry-field harvest"), details: LText(de: "Fahrt zu einem Selbstpflück-Feld und füllt eure Körbe. Die krummste Erdbeere wird gekrönt, die süßeste geteilt.", en: "Head to a pick-your-own field and fill your baskets. The wonkiest strawberry gets crowned, the sweetest gets shared."), indoor: false, budget: 1, tags: ["outdoor", "food"]),
        DateIdea(id: 254, emoji: "🏊", title: LText(de: "Freibad-Eröffnung", en: "Opening day at the lido"), details: LText(de: "Seid am ersten Tag der Freibadsaison dabei: kaltes Wasser, Pommes danach, Gänsehaut inklusive. Wer zuerst untertaucht, bekommt die erste Pommes.", en: "Be there on opening day of outdoor-pool season: cold water, fries afterwards, goosebumps included. First one fully under gets the first fry."), indoor: false, budget: 1, tags: ["outdoor", "adventure"]),
        DateIdea(id: 255, emoji: "⛈️", title: LText(de: "Gewitter-Kino", en: "Thunderstorm cinema"), details: LText(de: "Wenn ein Sommergewitter aufzieht: Licht aus, Snacks ans Fenster, beste Plätze sichern. Kommentiert die Blitze wie ein Feuerwerk.", en: "When a summer storm rolls in: lights off, snacks by the window, best seats in the house. Rate the lightning like a fireworks show."), indoor: true, budget: 0, tags: ["cozy", "athome", "night"], energy: .quick),
        DateIdea(id: 256, emoji: "🦶", title: LText(de: "Barfuß-Route", en: "Barefoot route"), details: LText(de: "Plant an einem warmen Tag eine kleine Barfuß-Strecke: Gras, Sand, warmer Asphalt, kaltes Wasser. Wer zuerst quietscht, verliert.", en: "On a warm day, plan a little barefoot course: grass, sand, warm pavement, cold water. First one to squeal loses."), indoor: false, budget: 0, tags: ["outdoor", "silly"], energy: .quick),
        DateIdea(id: 257, emoji: "🪁", title: LText(de: "Drachen ohne Anleitung", en: "Kite without instructions"), details: LText(de: "Baut aus Papier, Schnur und Klebeband einen Drachen — ohne Anleitung — und testet ihn am nächsten windigen Hügel. Absturz zählt als Kunstflug.", en: "Build a kite from paper, string, and tape — no instructions — and test it on the nearest windy hill. Crashing counts as aerobatics."), indoor: false, budget: 1, tags: ["creative", "outdoor"]),
        DateIdea(id: 258, emoji: "🍎", title: LText(de: "Apfelernte und Ofenduft", en: "Apple harvest, oven on"), details: LText(de: "Erst zum Obsthof oder Apfelbaum, dann in die Küche: Aus eurer Ernte wird noch am selben Tag etwas Warmes mit Zimt.", en: "First the orchard, then the kitchen: your harvest turns into something warm and cinnamon-scented the very same day."), indoor: false, budget: 1, tags: ["outdoor", "food", "cozy"]),
        DateIdea(id: 259, emoji: "❄️", title: LText(de: "Winterpicknick", en: "Winter picnic"), details: LText(de: "Packt Thermoskanne, Decke und belegte Brote und macht ein Picknick im Schnee oder Winterwald. Kalte Nasen, warme Hände — nach kurzer Rückfrage.", en: "Pack a thermos, a blanket, and sandwiches for a picnic in the snow or winter woods. Cold noses, warm hands — after a quick check-in."), indoor: false, budget: 0, tags: ["outdoor", "adventure", "cozy"]),
        DateIdea(id: 260, emoji: "⛄", title: LText(de: "Schneemann-Duell", en: "Snowman duel"), details: LText(de: "Beim nächsten richtigen Schnee: Jeder baut in dreißig Minuten seinen Schneemann. Die Nachbarschaft oder der Gruppenchat kürt den Sieger.", en: "Next proper snowfall: thirty minutes, one snowman each. The neighbors or the group chat crown the winner."), indoor: false, budget: 0, tags: ["outdoor", "silly"]),
        // Block 4 — gemischte neue Ideen.
        DateIdea(id: 261, emoji: "🪧", title: LText(de: "Bis ans Ortsschild", en: "Walk to the town sign"), details: LText(de: "Lauft gemeinsam bis zum Ortsschild eurer Stadt und macht das klassische Foto daneben — wie Reisende, die gerade angekommen sind.", en: "Walk all the way to your town's boundary sign and take the classic photo next to it — like travelers who just arrived."), indoor: false, budget: 0, tags: ["outdoor", "adventure"], energy: .quick),
        DateIdea(id: 262, emoji: "📖", title: LText(de: "Fremde Widmungen", en: "Strangers' dedications"), details: LText(de: "Stöbert im Antiquariat nach gebrauchten Büchern mit handschriftlichen Widmungen — und erfindet zu den schönsten die Geschichte dahinter.", en: "Browse a used bookstore for books with handwritten dedications — and invent the story behind the loveliest ones."), indoor: true, budget: 1, tags: ["creative", "cozy"]),
        DateIdea(id: 263, emoji: "🛝", title: LText(de: "Schaukeln bei Dämmerung", en: "Swings at dusk"), details: LText(de: "Geht nach Feierabend auf den leeren Spielplatz und schaukelt um die Wette, bis die Laternen angehen. Reden optional, Quietschen erlaubt.", en: "Hit the empty playground after work and swing side by side until the streetlights come on. Talking optional, squealing allowed."), indoor: false, budget: 0, tags: ["silly", "outdoor", "night"], energy: .quick),
        DateIdea(id: 264, emoji: "🛎️", title: LText(de: "Lobby-Touristen", en: "Lobby tourists"), details: LText(de: "Zieht euch fein an und trinkt etwas in der Lobby des schönsten Hotels der Stadt — als durchreisende Gäste mit erfundener Herkunftsgeschichte.", en: "Dress up and have a drink in the lobby of the fanciest hotel in town — as travelers passing through, invented backstory included."), indoor: true, budget: 2, tags: ["silly", "romantic"]),
        DateIdea(id: 265, emoji: "🥕", title: LText(de: "Marktschluss-Menü", en: "Closing-time market menu"), details: LText(de: "Geht in der letzten Stunde über den Wochenmarkt und kocht aus den Schnäppchen der Stände ein Überraschungsmenü — der Markt entscheidet, was es gibt.", en: "Hit the farmers' market in its final hour and cook a surprise menu from the last-minute bargains — the market decides what's for dinner."), indoor: false, budget: 1, tags: ["food", "outdoor"]),
        DateIdea(id: 266, emoji: "👂", title: LText(de: "Lausch-Runde", en: "Listening loop"), details: LText(de: "Spaziert zwanzig Minuten schweigend und sammelt Geräusche: das fernste, das leiseste, das schönste. Danach werden die Listen verglichen.", en: "Walk in silence for twenty minutes and collect sounds: the farthest, the quietest, the most beautiful. Compare lists afterwards."), indoor: false, budget: 0, tags: ["outdoor", "cozy"], energy: .quick),
        DateIdea(id: 267, emoji: "🖼️", title: LText(de: "Flohmarkt-Kuratoren", en: "Flea-market curators"), details: LText(de: "Schlendert über den Flohmarkt und kuratiert eine imaginäre Ausstellung: Jeder wählt fünf Stücke für das Museum eurer Beziehung. Gekauft wird nichts — außer vielleicht doch.", en: "Stroll the flea market and curate an imaginary exhibition: each of you picks five pieces for the museum of your relationship. Buy nothing — well, probably nothing."), indoor: false, budget: 0, tags: ["silly", "creative", "outdoor"]),
        DateIdea(id: 268, emoji: "🏸", title: LText(de: "Federball bis zur Dunkelheit", en: "Badminton till dark"), details: LText(de: "Spielt Federball im Park, bis ihr den Ball nicht mehr seht. Zählen zwecklos, Ehrgeiz trotzdem erlaubt.", en: "Play badminton in the park until you literally can't see the shuttle anymore. Keeping score is futile; competitiveness is still allowed."), indoor: false, budget: 1, tags: ["outdoor", "silly"]),
        DateIdea(id: 269, emoji: "🛋️", title: LText(de: "Möbelhaus-Probewohnen", en: "Showroom test living"), details: LText(de: "Spaziert durchs Möbelhaus und zieht probeweise ein: Hier das Wohnzimmer, da die Küche. Diskutiert ernsthaft, ob das Bücherregal zu eurem imaginären Flur passt.", en: "Wander the furniture store and move in, hypothetically: living room here, kitchen there. Debate in complete seriousness whether the bookshelf suits your imaginary hallway."), indoor: true, budget: 0, tags: ["silly", "cozy"]),
        DateIdea(id: 270, emoji: "🔮", title: LText(de: "Horoskop-Redaktion", en: "Horoscope editors"), details: LText(de: "Lest euch eure heutigen Horoskope vor — und schreibt dann bessere füreinander. Präzise Vorhersagen über Kaffeekonsum und Kuschelbedarf erwünscht.", en: "Read today's horoscopes aloud — then write better ones for each other. Precise forecasts on coffee intake and cuddle demand encouraged."), indoor: true, budget: 0, tags: ["silly", "creative", "athome"], energy: .quick),
        DateIdea(id: 271, emoji: "🚶", title: LText(de: "Wander-Dinner", en: "Progressive dinner walk"), details: LText(de: "Esst jeden Gang woanders: Vorspeise am Imbiss, Hauptgang im Lieblingslokal, Nachtisch von der Eisdiele — die Stadt ist euer Menü.", en: "Eat every course somewhere else: starter at the snack stand, main at your favorite spot, dessert from the gelato place — the city is your menu."), indoor: false, budget: 2, tags: ["food", "outdoor", "adventure"]),
        DateIdea(id: 272, emoji: "🚲", title: LText(de: "Tandem-Premiere", en: "Tandem premiere"), details: LText(de: "Leiht euch ein Tandem und findet heraus, wer vorne besser lenkt und wer hinten besser kommentiert. Kurven werden gemeinsam beschlossen.", en: "Rent a tandem bike and find out who steers better up front and who commentates better in back. Turns are a joint decision."), indoor: false, budget: 2, tags: ["adventure", "outdoor", "silly"]),
        DateIdea(id: 273, emoji: "🎰", title: LText(de: "Wochen-Wettbüro", en: "The weekly betting office"), details: LText(de: "Schließt kleine Wetten auf euren Alltag ab: Wie oft klingelt morgen das Telefon, welche Schlange an der Kasse ist schneller? Einsatz: Frühstück ans Bett.", en: "Place small bets on your everyday life: how often will the phone ring tomorrow, which checkout line is faster? Stakes: breakfast in bed."), indoor: true, budget: 0, tags: ["silly", "athome"], energy: .quick),
        DateIdea(id: 274, emoji: "🎓", title: LText(de: "Kurs-Katalog-Lotterie", en: "Course-catalog lottery"), details: LText(de: "Blättert durch das Kursprogramm der Volkshochschule und wählt heimlich je einen Kurs für den anderen. Die Enthüllung ist das Date — die Anmeldung Verhandlungssache.", en: "Flip through the community-college catalog and secretly pick one course for each other. The reveal is the date — actually enrolling is up for negotiation."), indoor: true, budget: 0, tags: ["creative", "athome"], energy: .quick),
        DateIdea(id: 275, emoji: "🌿", title: LText(de: "Wildkräuter-Expedition", en: "Wild-herb expedition"), details: LText(de: "Zieht mit einer Bestimmungs-App los und findet drei essbare Wildkräuter. Was ihr sicher erkennt, landet abends auf dem Butterbrot.", en: "Head out with a plant-ID app and find three edible wild herbs. Whatever you identify with certainty ends up on your bread tonight."), indoor: false, budget: 0, tags: ["outdoor", "adventure", "food"]),
        DateIdea(id: 276, emoji: "🧥", title: LText(de: "Stilberatung Secondhand", en: "Thrift-store stylists"), details: LText(de: "Stellt euch im Secondhand-Laden gegenseitig ein komplettes Outfit zusammen — Budget: zehn Euro. Anprobe ist Pflicht, Fotobeweis auch.", en: "Style each other one complete outfit at the thrift store — budget: ten euros. Trying it on is mandatory; so is photo evidence."), indoor: true, budget: 1, tags: ["silly", "creative"]),
        DateIdea(id: 277, emoji: "🐠", title: LText(de: "Aquarium in Zeitlupe", en: "Aquarium in slow motion"), details: LText(de: "Besucht ein Aquarium und macht es zum Wettbewerb der Langsamkeit: Wer bleibt länger vor einem Becken stehen? Am Ende adoptiert jeder auf dem Papier einen Fisch.", en: "Visit an aquarium and turn it into a slowness contest: who can linger longer at one tank? At the end, each of you adopts a fish, on paper."), indoor: true, budget: 2, tags: ["cozy", "adventure"]),
        DateIdea(id: 278, emoji: "🤟", title: LText(de: "Stille Sprache", en: "Silent language"), details: LText(de: "Lernt gemeinsam zehn Gebärden — darunter Ich liebe dich — und führt beim Abendessen ein Gespräch nur mit den Händen.", en: "Learn ten signs together — including I love you — and hold a dinner conversation using only your hands."), indoor: true, budget: 0, tags: ["creative", "cozy", "athome"], energy: .quick),
        DateIdea(id: 279, emoji: "🗞️", title: LText(de: "Geburtsjahr-Zeitung", en: "Birth-year newspaper"), details: LText(de: "Sucht online die Zeitung vom Geburtstag von einem von euch und lest sie gemeinsam: Schlagzeilen, Kinoprogramm, Kleinanzeigen — die Welt, in die ihr geboren wurdet.", en: "Find the newspaper from the day one of you was born and read it together: headlines, cinema listings, classifieds — the world you were born into."), indoor: true, budget: 0, tags: ["cozy", "creative", "athome"]),
        DateIdea(id: 280, emoji: "🖨️", title: LText(de: "Zehn Bilder aus dem Handy", en: "Ten photos off the phone"), details: LText(de: "Wählt je fünf Handyfotos, druckt sie am Automaten aus und hängt zuhause eine Mini-Vernissage auf — mit Titelschildchen und Eröffnungsrede.", en: "Pick five phone photos each, print them at a kiosk, and hang a mini vernissage at home — title cards and opening speech included."), indoor: true, budget: 1, tags: ["creative", "romantic"]),
        DateIdea(id: 281, emoji: "🍨", title: LText(de: "Beutel-Eiscreme", en: "Bag-shake ice cream"), details: LText(de: "Macht Eis ohne Maschine: Sahne, Zucker und Vanille in einen Beutel, Eiswürfel und Salz drumherum — und dann wird geschüttelt, bis es Eis ist. Muskelkater inklusive.", en: "Make ice cream without a machine: cream, sugar, and vanilla in one bag, ice and salt around it — then shake until it's ice cream. Sore arms included."), indoor: true, budget: 1, tags: ["food", "silly", "athome"]),
        DateIdea(id: 282, emoji: "🏡", title: LText(de: "Vorgarten-Jury", en: "Front-yard jury"), details: LText(de: "Spaziert durch eure Straße und vergebt Preise: schönste Haustür, mutigste Gartendeko, bester Briefkasten. Die Preisverleihung findet flüsternd statt.", en: "Walk your street and hand out awards: loveliest front door, boldest garden decor, best mailbox. The ceremony is held in whispers."), indoor: false, budget: 0, tags: ["silly", "outdoor"], energy: .quick)
    ]
}
